INSERT INTO books (isbn, title, author, publisher, publication_year, available_copies, genre, summary, cover_url) VALUES
    ('9780736692403', 'Dune', 'Frank Herbert', 'Books on Tape, inc.', 1965, 1, 'Science fiction', 'Set on the desert planet Arrakis, Dune is the story of the boy Paul Atreides, heir to a noble family tasked with ruling an inhospitable world where the only thing of value is the "spice" melange, a drug capable of extending life and enhancing consciousness. Coveted across the known universe, melange is a prize worth killing for... When House Atreides is betrayed, the destruction of Paul''s family will set the boy on a journey toward a destiny greater than he could ever have imagined. And as he evolves into the mysterious man known as Muad''Dib, he will bring to fruition humankind''s most ancient and unattainable dream. A stunning blend of adventure and mysticism, environmentalism and politics, Dune won the first Nebula Award, shared the Hugo Award, and formed the basis of what is undoubtedly the grandest epic in science fiction.', 'https://covers.openlibrary.org/b/id/14020316-M.jpg'),
    ('9780008117498', 'Foundation', 'Isaac Asimov', 'HARPER COLLINS', 1951, 0, 'Science fiction', 'One of the great masterworks of science fiction, the Foundation novels of Isaac Asimov are unsurpassed for their unique blend of nonstop action, daring ideas, and extensive world-building. The story of our future begins with the history of Foundation and its greatest psychohistorian: Hari Seldon. For twelve thousand years the Galactic Empire has ruled supreme. Now it is dying. Only Hari Seldon, creator of the revolutionary science of psychohistory, can see into the future--a dark age of ignorance, barbarism, and warfare that will last thirty thousand years. To preserve knowledge and save mankind, Seldon gathers the best minds in the Empire--both scientists and scholars--and brings them to a bleak planet at the edge of the Galaxy to serve as a beacon of hope for future generations. He calls his sanctuary the Foundation.', 'https://covers.openlibrary.org/b/id/14637494-M.jpg'),
    ('9780007383290', 'Neuromancer', 'William Gibson', 'HarperCollins Publishers Limited', 1984, 2, 'Science fiction', 'The first of William Gibson''s Sprawl trilogy, Neuromancer is the classic cyberpunk novel. The winner of the Hugo, Nebula, and Philip K. Dick Awards, Neuromancer was the first fully-realized glimpse of humankind’s digital future — a shocking vision that has challenged our assumptions about our technology and ourselves, reinvented the way we speak and think, and forever altered the landscape of our imaginations. Henry Dorsett Case was the sharpest data-thief in the business, until vengeful former employees crippled his nervous system. But now a new and very mysterious employer recruits him for a last-chance run. The target: an unthinkably powerful artificial intelligence orbiting Earth in service of the sinister Tessier-Ashpool business clan.', 'https://covers.openlibrary.org/b/id/14389185-M.jpg'),
    ('9781399638319', 'The Left Hand of Darkness', 'Ursula K. Le Guin', 'Weidenfield & Nicolson', 1969, 3, 'Science fiction', 'Comment by Kim Stanley Robinson, on The Guardian''s website: The Left Hand of Darkness by Ursula K Le Guin (1969) > One of my favorite novels is The Left Hand of Darkness, by Ursula K Le Guin. For more than 40 years I''ve been recommending this book to people who want to try science fiction for the first time, and it still serves very well for that. One of the things I like about it is how clearly it demonstrates that science fiction can have not only the usual virtues and pleasures of the novel, but also the startling and transformative power of the thought experiment. > In this case, the thought experiment is quickly revealed: "The king was pregnant," the book tells us early on, and after that we learn more and more about this planet named Winter, stuck in an ice age, where the humans are most of the time neither male nor female, but with the potential to become either.', 'https://covers.openlibrary.org/b/id/15265232-M.jpg'),
    ('9780765342294', 'Ender''s Game', 'Orson Scott Card', 'Starscape', 1985, 0, 'Science fiction', 'Ender''s Game is a 1985 military science fiction novel by American author Orson Scott Card. Set at an unspecified date in Earth''s future, the novel presents an imperiled humankind after two conflicts with the Formics, an insectoid alien species they dub the "buggers". In preparation for an anticipated third invasion, children, including the novel''s protagonist, Andrew "Ender" Wiggin, are trained from a very young age by putting them through increasingly difficult games, including some in zero gravity, where Ender''s tactical genius is revealed. The book originated as a short story of the same name, published in the August 1977 issue of Analog Science Fiction and Fact. The novel was published on January 15, 1985. Later, by elaborating on characters and plotlines depicted in the novel, Card was able to write additional books in the Ender''s Game series.', 'https://covers.openlibrary.org/b/id/15254262-M.jpg'),
    ('9781491523223', 'The Martian', 'Andy Weir', 'Podium Publishing on Brilliance Audio', 2011, 2, 'Science fiction', 'The Martian is a 2011 science fiction novel written by Andy Weir. It was his debut novel under his own name. It was originally self-published in 2011; Crown Publishing purchased the rights and re-released it in 2014. The story follows an American astronaut, Mark Watney, as he becomes stranded alone on Mars in 2035 and must improvise in order to survive.', 'https://covers.openlibrary.org/b/id/13832054-M.jpg'),
    ('9781491514979', 'Hyperion', 'Dan Simmons', 'Brilliance Audio', 1989, 0, 'Science fiction', 'In the 29th century, the Hegemony of Man comprises hundreds of planets connected by farcaster portals. The Hegemony maintains an uneasy alliance with the TechnoCore, a civilisation of AIs. Modified humans known as Ousters live in space stations between stars and are engaged in conflict with the Hegemony. Numerous "Outback" planets have no farcasters and cannot be accessed without incurring significant time dilation. One of these planets is Hyperion, home to structures known as the Time Tombs, which are moving backwards in time and guarded by a legendary creature known as the Shrike. On the eve of an Ouster invasion of Hyperion, a final pilgrimage to the Time Tombs has been organized. The pilgrims decide that they will each tell their tale of how they were chosen for the pilgrimage.', 'https://covers.openlibrary.org/b/id/10655638-M.jpg'),
    ('9780451038005', 'Do Androids Dream of Electric Sheep?', 'Philip K. Dick', 'Penguin Publishing Group', 1968, 4, 'Science fiction', 'It was January 2021, and Rick Deckard had a license to kill. Somewhere among the hordes of humans out there, lurked several rogue androids. Deckard''s assignment--find them and then..."retire" them. Trouble was, the androids all looked exactly like humans, and they didn''t want to be found!', 'https://covers.openlibrary.org/b/id/14435531-M.jpg'),
    ('9781405053976', 'The Hitchhiker''s Guide to the Galaxy', 'Douglas Adams', 'Macmillan Audio Books', 1979, 1, 'Science fiction', 'The Hitchhiker''s Guide to the Galaxy is the first of six books in the Hitchhiker''s Guide to the Galaxy comedy science fiction "hexalogy" by Douglas Adams. The novel is an adaptation of the first four parts of Adams''s radio series of the same name. The novel was first published in London on 12 October 1979. It sold 250,000 copies in the first three months. The namesake of the novel is The Hitchhiker''s Guide to the Galaxy, a fictional guide book for hitchhikers (inspired by the Hitch-hiker''s Guide to Europe) written in the form of an encyclopaedia.', 'https://covers.openlibrary.org/b/id/14848869-M.jpg'),
    ('9783125777903', 'Brave New World', 'Aldous Huxley', 'Vintage', 1932, 1, 'Science fiction', 'Originally published in 1932, this outstanding work of literature is more crucial and relevant today than ever before. Cloning, feel-good drugs, antiaging programs, and total social control through politics, programming, and media -- has Aldous Huxley accurately predicted our future? With a storyteller''s genius, he weaves these ethical controversies in a compelling narrative that dawns in the year 632 AF (After Ford, the deity). When Lenina and Bernard visit a savage reservation, we experience how Utopia can destroy humanity. A powerful work of speculative fiction that has enthralled and terrified readers for generations, Brave New World is both a warning to be heeded and thought-provoking yet satisfying entertainment. - Container.', 'https://covers.openlibrary.org/b/id/15170715-M.jpg'),
    ('9780143425809', 'Nineteen Eighty-Four', 'George Orwell', 'Penguin Books', 1949, 1, 'Science fiction', 'Nineteen Eighty-Four: A Novel, often referred to as 1984, is a dystopian social science fiction novel by the English novelist George Orwell (the pen name of Eric Arthur Blair). It was published on 8 June 1949 by Secker & Warburg as Orwell''s ninth and final book completed in his lifetime. Thematically, Nineteen Eighty-Four centres on the consequences of totalitarianism, mass surveillance, and repressive regimentation of persons and behaviours within society. Orwell, himself a democratic socialist, modelled the authoritarian government in the novel after Stalinist Russia. More broadly, the novel examines the role of truth and facts within politics and the ways in which they are manipulated.', 'https://covers.openlibrary.org/b/id/15257423-M.jpg'),
    ('9780006546061', 'Fahrenheit 451', 'Ray Bradbury', 'HarperVoyager', 1953, 2, 'Science fiction', 'Fahrenheit 451 is a 1953 dystopian novel by American writer Ray Bradbury. Often regarded as one of his best works, the novel presents a future American society where books are outlawed and "firemen" burn any that are found. The book''s tagline explains the title as "''the temperature at which book paper catches fire, and burns": the autoignition temperature of paper. The lead character, Guy Montag, is a fireman who becomes disillusioned with his role of censoring literature and destroying knowledge, eventually quitting his job and committing himself to the preservation of literary and cultural writings. The novel has been the subject of interpretations focusing on the historical role of book burning in suppressing dissenting ideas for change.', 'https://covers.openlibrary.org/b/id/15265555-M.jpg'),
    ('9781967200085', 'The War of the Worlds', 'H. G. Wells', 'GoArchitect', 1898, 3, 'Science fiction', 'The ultimate science fiction classic: for more than one hundred years, this compelling tale of the Martian invasion of Earth has enthralled readers with a combination of imagination and incisive commentary on the imbalance of power that continues to be relevant today. The style is revolutionary for its era, employing a sophisticated first and third person account of the events which is both personal and focused on the holistic downfall of Earth''s society. The Martians, as evil, mechanical and unknown a threat they are, remain daunting in today''s society, where, despite technology''s mammoth advances, humanity''s hegemony over Earth is yet to be called into question.', 'https://covers.openlibrary.org/b/id/15067137-M.jpg'),
    ('9780141884806', 'Snow Crash', 'Neal Stephenson', 'Penguin Books, Limited', 1992, 2, 'Science fiction', 'Within the Metaverse, Hiro is offered a datafile named Snow Crash by a man named Raven who hints that it is a form of narcotic. Hiro''s friend and fellow hacker Da5id views a bitmap image contained in the file which causes his computer to crash and Da5id to suffer brain damage in the real world. This is the future we now live where all can be brought to life in the metaverse and now all can be taken away. Follow on an adventure with Hiro and YT as they work with the mob to uncover a plot of biblical proportions.', 'https://covers.openlibrary.org/b/id/14138356-M.jpg'),
    ('9780521852241', 'The Three-Body Problem', 'Liu Cixin', 'Cambridge University Press', 2008, 2, 'Science fiction', 'How do three celestial bodies move under their mutual gravitational attraction? This problem has been studied by Isaac Newton and leading mathematicians over the last two centuries. PoincarE''s conclusion, that the problem represents an example of chaos in nature, opens the new possibility of using a statistical approach. For the first time this book presents these methods in a systematic way, surveying statistical as well as more traditional methods. The book begins by providing an introduction to celestial mechanics, including Lagrangian and Hamiltonian methods, and both the two and restricted three body problems. It then surveys statistical and perturbation methods for the solution of the general three body problem, providing solutions based on combining orbit calculations with semi-analytic methods for the first time.', 'https://covers.openlibrary.org/b/id/359487-M.jpg'),
    ('9780241467992', 'The Cyberiad', 'Stanisław Lem', 'Penguin Random House UK', 1965, 0, 'Science fiction', 'OMG I can''t believe there''s no description for this - but then I can because this book defies description. Stanislaw Lem is a genius and your minds will be expanded to bursting when you begin this journey into a world where machines are the dominant species. It is hugely entertaining, inventive, witty, and above all, laugh out loud funny. The book concerns two "constructors" - Trurl and Klaupacious who build machines, and who are in fact machines themselves. Find out what happens when Trurl builds the world''s stupidest computer, and Klaupacious'' machine that can do "anything in N" nearly ends the universe.', 'https://covers.openlibrary.org/b/id/14602620-M.jpg'),
    ('9780008537722', 'The Fellowship of the Ring', 'J. R. R. Tolkien', 'HarperCollins Publishers', 1954, 1, 'Fantasy', 'One Ring to rule them all, One Ring to find them, One Ring to bring them all and in the darkness bind them. “A unique, wholly realized other world, evoked from deep in the well of Time, massively detailed, absorbingly entertaining, profound in meaning.”—The New York Times In ancient times the Rings of Power were crafted by the Elven-smiths, and Sauron, the Dark Lord, forged the One Ring, filling it with his own power so that he could rule all others. But the One Ring was taken from him, and though he sought it throughout Middle-earth, it remained lost to him. After many ages it fell into the hands of Bilbo Baggins, as told in The Hobbit. In a sleepy village in the Shire, young Frodo Baggins finds himself faced with an immense task, as his elderly cousin Bilbo entrusts the Ring to his care.', 'https://covers.openlibrary.org/b/id/15244480-M.jpg'),
    ('9780553381689', 'A Game of Thrones', 'George R. R. Martin', 'Random House Worlds', 1996, 3, 'Fantasy', '*A Game of Thrones is the inaugural novel in A Song of Ice and Fire, an epic series of fantasy novels crafted by the American author George R. R. Martin. Published on August 1, 1996, this novel introduces readers to the richly detailed world of Westeros and Essos, where political intrigue, power struggles, and magical elements intertwine. The story unfolds through multiple perspectives, each chapter focusing on a different character, allowing readers to experience the narrative from various angles. This complex structure has become a hallmark of Martin''s storytelling, immersing readers in the lives and motivations of a diverse cast. ### Plot Summary Set in the fictional continents of Westeros and Essos, the narrative revolves around the power struggles among noble families vying for the Iron Throne, the seat of power in the Seven Kingdoms of Westeros.', 'https://covers.openlibrary.org/b/id/15237705-M.jpg'),
    ('9781525300042', 'The Last Wish', 'Andrzej Sapkowski', 'Kids Can Press', 1993, 2, 'Fantasy', 'Short stories that introduce Geralt of Rivia, a witcher who hunts monsters for money and keeps finding that the people who hire him are the real danger.', 'https://covers.openlibrary.org/b/id/9220058-M.jpg'),
    ('9781551927282', 'Harry Potter and the Philosopher''s Stone', 'J. K. Rowling', 'Raincoast Books', 1997, 1, 'Fantasy', 'Turning the envelope over, his hand trembling, Harry saw a purple wax seal bearing a coat of arms; a lion, an eagle, a badger and a snake surrounding a large letter ''H''. HARRY POTTER has never even heard of Hogwarts when the LETTERS start dropping on the doormat at number four, Privet Drive. Addressed in GREEN INK on yellowish parchment with a PURPLE SEAL, they are swiftly confiscated by his GRISLY aunt and uncle. Then, on Harry''s eleventh birthday, a great beetle-eyed giant of a man called RUBEUS HAGRID bursts in with some ASTONISHING news: Harry Potter is a wizard, and he has a place at Hogwarts School of Witchcraft and Wizardry. An incredible adventure is about to begin!', 'https://covers.openlibrary.org/b/id/15263570-M.jpg'),
    ('9781423389286', 'The Name of the Wind', 'Patrick Rothfuss', 'Brilliance Audio', 2007, 0, 'Fantasy', '*The Name of the Wind, also called The Kingkiller Chronicle: Day One, is a heroic fantasy novel written by American author Patrick Rothfuss. It is the first book in the ongoing fantasy trilogy The Kingkiller Chronicle. It was published on March 27, 2007, by DAW Books, the novel has been hailed as a masterpiece of high fantasy. The story begins the tale of Kvothe (pronounced "quothe"), a young man who becomes the most notorious magician his world has ever known. Kvothe narrates his own journey, from his childhood in a troupe of traveling players to his years as a near-feral orphan in a crime-ridden city, and his daring entrance into a prestigious and perilous school of magic. Patrick Rothfuss''s debut novel has been praised for its fresh and earthy originality, transporting readers into the mind of a wizard and the world that shaped him.', 'https://covers.openlibrary.org/b/id/13169445-M.jpg'),
    ('9781473226814', 'A Wizard of Earthsea', 'Ursula K. Le Guin', 'Orion', 1968, 2, 'Fantasy', 'The first novel of Ursula K. Le Guin''s must-read Earthsea Cycle. "The magic of Earthsea is primal; the lessons of Earthsea remain as potent, as wise, and as necessary as anyone could dream." (Neil Gaiman) Ged was the greatest sorcerer in Earthsea, but in his youth he was the reckless Sparrowhawk. In his hunger for power and knowledge, he tampered with long-held secrets and loosed a terrible shadow upon the world. This is the tumultuous tale of his testing, how he mastered the mighty words of power, tamed an ancient dragon, and crossed death''s threshold to restore the balance. With stories as perennial and universally beloved as The Chronicles of Narnia and The Lord of The Rings—but also unlike anything but themselves—Ursula K. Le Guin’s Earthsea novels are some of the most acclaimed and awarded works in literature.', 'https://covers.openlibrary.org/b/id/15231478-M.jpg'),
    ('9781648813542', 'The Way of Kings', 'Brandon Sanderson', 'Graphic Audio, LLC.', 2010, 2, 'Fantasy', 'Widely acclaimed for his work completing Robert Jordan’s Wheel of Time saga, Brandon Sanderson now begins a grand cycle of his own, one every bit as ambitious and immersive. Roshar is a world of stone and storms. Uncanny tempests of incredible power sweep across the rocky terrain so frequently that they have shaped ecology and civilization alike. Animals hide in shells, trees pull in branches, and grass retracts into the soilless ground. Cities are built only where the topography offers shelter. It has been centuries since the fall of the ten consecrated orders known as the Knights Radiant, but their Shardblades and Shardplate remain: mystical swords and suits of armor that transform ordinary men into near-invincible warriors. Men trade kingdoms for Shardblades. Wars are fought for them, and won by them. One such war rages on a ruined landscape called the Shattered Plains.', 'https://covers.openlibrary.org/b/id/15167401-M.jpg'),
    ('9781538462102', 'American Gods', 'Neil Gaiman', 'HarperCollins Publishers and Blackstone Audio', 2001, 2, 'Fantasy', 'American Gods (2001) is a fantasy novel by British author Neil Gaiman. The novel is a blend of Americana, fantasy, and various strands of ancient and modern mythology, all centering on the mysterious and taciturn Shadow.', 'https://covers.openlibrary.org/b/id/14399052-M.jpg'),
    ('9780061991127', 'Good Omens', 'Terry Pratchett, Neil Gaiman', 'HarperCollins', 1990, 2, 'Fantasy', 'Armageddon only happens once, you know. They don''t let you go around again until you get it right. According to the Nice and Accurate Prophecies of Agnes Nutter, Witch - the world''s only totally reliable guide to the future, written in 1655, before she exploded - the world will end on a Saturday. Next Saturday, in fact. Just after tea... People have been predicting the end of the world almost from its very beginning, so it''s only natural to be sceptical when a new date is set for Judgement Day. This time though, the armies of Good and Evil really do appear to be massing. The four Bikers of the Apocalypse are hitting the road. But both the angels and demons - well, one fast-living demon and a somewhat fussy angel - would quite like the Rapture not to happen. Oh, and someone seems to have misplaced the Antichrist...', 'https://covers.openlibrary.org/b/id/14657945-M.jpg'),
    ('9780063373662', 'The Colour of Magic', 'Terry Pratchett', 'HarperCollins Publishers', 1983, 0, 'Fantasy', 'Terry Pratchett''s profoundly irreverent novels are consistent number one bestsellers in England, where they have garnered him a revered position in the halls of parody next to Mark Twain, Kurt Vonnegut, Douglas Adams, and Carl Hiaasen.The Color of Magic is Terry Pratchett''s maiden voyage through the now-legendary land of Discworld. This is where it all begins--with the tourist Twoflower and his wizard guide, Rincewind.', 'https://covers.openlibrary.org/b/id/15223765-M.jpg'),
    ('9781593974558', 'The Eye of the World', 'Robert Jordan', 'Macmillan Audio', 1990, 1, 'Fantasy', 'The Wheel of Time turns and Ages come and go, leaving memories that become legend. Legend fades to myth, and even myth is long forgotten when the Age that gave it birth returns again. In the Third Age, an Age of Prophecy, the World and Time themselves hang in the balance. What was, what will be, and what is, may yet fall under the Shadow.', 'https://covers.openlibrary.org/b/id/14837571-M.jpg'),
    ('9781526677181', 'Jonathan Strange & Mr Norrell', 'Susanna Clarke', 'Bloomsbury Publishing', 2004, 1, 'Fantasy', 'Published in 2004, it is an alternative history set in 19th-century England around the time of the Napoleonic Wars. Its premise is that magic once existed in England and has returned with two men: Gilbert Norrell and Jonathan Strange. Centred on the relationship between these two men, the novel investigates the nature of "Englishness" and the boundaries between reason and unreason, Anglo-Saxon and Anglo-Dane, and Northern and Southern English cultural tropes/stereotypes. It has been described as a fantasy novel, an alternative history, and a historical novel. It inverts the Industrial Revolution conception of the North-South divide in England: in this book the North is romantic and magical, rather than rational and concrete.', 'https://covers.openlibrary.org/b/id/15124416-M.jpg'),
    ('9781473216792', 'The Lies of Locke Lamora', 'Scott Lynch', 'Gollancz', 2006, 0, 'Fantasy', 'In the canal city of Camorr, the orphan thief Locke Lamora and his gang con the nobility, until a mysterious rival starts killing the city''s crime bosses.', 'https://covers.openlibrary.org/b/id/8777184-M.jpg'),
    ('9780060010836', 'Stardust', 'Neil Gaiman', 'Perfectbound', 1999, 2, 'Fantasy', 'E-book extra: Neil Gaiman''s "Writing and the Imagination."In the tranquil fields and meadows of long-ago England, there is a small hamlet that has stood on a jut of granite for 600 years. Just to the east stands a high stone wall, for which the village is named. Here, in the hamlet of Wall, young Tristran Thorn has lost his heart to the hauntingly beautiful Victoria Forester. And here, one crisp October eve, Tristran makes his love a promise -- an impetuous vow that will send him through the only breach in the wall, across the pasture ... and into the most exhilarating adventure of his life.', 'https://covers.openlibrary.org/b/id/10942072-M.jpg'),
    ('9780460871563', 'The Hound of the Baskervilles', 'Arthur Conan Doyle', 'Phoenix (an Imprint of The Orion Publishing Group Ltd )', 1902, 1, 'Mystery', 'The Hound of the Baskervilles is the third of the four crime novels by British writer Arthur Conan Doyle featuring the detective Sherlock Holmes. Originally serialised in The Strand Magazine from August 1901 to April 1902, it is set in 1889 largely on Dartmoor in Devon in England''s West Country and tells the story of an attempted murder inspired by the legend of a fearsome, diabolical hound of supernatural origin. Holmes and Watson investigate the case. This was the first appearance of Holmes since his apparent death in "The Final Problem", and the success of The Hound of the Baskervilles led to the character''s eventual revival. One of the most famous stories ever written, in 2003, the book was listed as number 128 of 200 on the BBC''s The Big Read poll of the UK''s "best-loved novel". In 1999, a poll of "Sherlockians" ranked it as the best of the four Holmes novels.', 'https://covers.openlibrary.org/b/id/4638176-M.jpg'),
    ('9781774537923', 'A Study in Scarlet', 'Arthur Conan Doyle', 'Rakuten Kobo', 1887, 4, 'Mystery', 'A Study in Scarlet is an 1887 detective novel by British writer Arthur Conan Doyle. The story marks the first appearance of Sherlock Holmes and Dr. Watson, who would become the most famous detective duo in literature.', 'https://covers.openlibrary.org/b/id/15148536-M.jpg'),
    ('9781405892148', 'Murder on the Orient Express', 'Agatha Christie', 'Pearson Education, Limited', 1934, 3, 'Mystery', '*While en route from Syria to Paris, in the middle of a freezing winter''s night, the Orient Express is stopped dead in its tracks by a snowdrift. Passengers awake to find the train still stranded and to discover that a wealthy American has been brutally stabbed to death in his private compartment. Incredibly, that compartment is locked from the inside. With no escape into the wintery landscape the killer must still be on board. Fortunately, the brilliant Belgian inspector Hercule Poirot is also on board, having booked the last available berth.', 'https://covers.openlibrary.org/b/id/13875296-M.jpg'),
    ('9780671754013', 'And Then There Were None', 'Agatha Christie', 'St. Martin''s Griffin', 1939, 1, 'Mystery', 'And Then There Were None is a mystery novel by the English writer Agatha Christie, described by her as the most difficult of her books to write. It was first published in the United Kingdom by the Collins Crime Club on 6 November 1939, as Ten Little Niggers, after the children''s counting rhyme and minstrel song, which serves as a major element of the plot. A US edition was released in January 1940 with the title And Then There Were None, which is taken from the last five words of the song. All successive American reprints and adaptations use that title, except for the Pocket Books paperbacks published between 1964 and 1986, which appeared under the title Ten Little Indians. UK editions continued to use the original title until the current definitive title appeared with a reprint of the 1963 Fontana Paperback in 1985.', 'https://covers.openlibrary.org/b/id/15244938-M.jpg'),
    ('9781684226566', 'The Murder of Roger Ackroyd', 'Agatha Christie', 'Martino Fine Books', 1926, 3, 'Mystery', 'Belgian Inspector Hercule Poirot has retired to the countryside in the small English village of King''s Abbot. Dr. Sheppard, observing his new neighbor, is sure that he must be a former hairdresser. But the brutal murder of a local squire reveals the truth: the peculiar little man is actually a detective par excellence. The Murder of the wealthy industrialist Roger Ackroyd begins the night before with the suicide of Mrs. Ferrars, a wealthy widow. Her death is believed to be an accident, until Roger Ackroyd is stabbed to death in his locked study. There are rumors she poisoned her first husband, rumors that she was being blackmailed, rumors that her secret lover was Roger Ackroyd, a man who knew too much, but no one is sure.', 'https://covers.openlibrary.org/b/id/14586849-M.jpg'),
    ('9781401242862', 'The Girl with the Dragon Tattoo', 'Stieg Larsson', 'Vertigo', 2005, 1, 'Mystery', 'A disgraced journalist and a brilliant, guarded hacker investigate the decades-old disappearance of a girl from one of Sweden''s richest families.', 'https://covers.openlibrary.org/b/id/10858749-M.jpg'),
    ('9780753827666', 'Gone Girl', 'Gillian Flynn', 'Phoenix', 2012, 2, 'Mystery', 'Gone Girl is a 2012 crime thriller novel by American writer Gillian Flynn. It was published by Crown Publishing Group in June 2012. The novel became popular and made the New York Times Best Seller list. The sense of suspense in the novel comes from whether or not Nick Dunne is involved in the disappearance of his wife Amy.', 'https://covers.openlibrary.org/b/id/14408542-M.jpg'),
    ('9781978666023', 'The Big Sleep', 'Raymond Chandler', 'Audible Studios on Brilliance', 1939, 3, 'Mystery', 'Philip Marlowe, a private eye who operates in Los Angeles''s seamy underside during the 1930s, takes on his first case, which involves a paralyzed California millionaire, two psychotic daughters, blackmail, and murder', 'https://covers.openlibrary.org/b/id/11408668-M.jpg'),
    ('9781572703636', 'The Maltese Falcon', 'Dashiell Hammett', 'The Audio Partners, Mystery Masters', 1930, 1, 'Mystery', 'Classic noir. Private detective Sam Spade is hired to search for a valuable, gem-encrusted antique in the shape of a falcon. Sam Spade is hired by the fragrant Miss Wonderley to track down her sister, who has eloped with a louse called Floyd Thursby. But Miss Wonderley is in fact the beautiful and treacherous Brigid O''Shaughnessy, and when Spade''s partner Miles Archer is shot while on Thursby''s trail, Spade finds himself both hunter and hunted: can he track down the jewel-encrusted bird, a treasure worth killing for, before the Fat Man finds him?', 'https://covers.openlibrary.org/b/id/1922015-M.jpg'),
    ('9780739313114', 'The Da Vinci Code', 'Dan Brown', 'Brand: Random House Audio', 2003, 4, 'Mystery', 'The Da Vinci Code is a 2003 mystery thriller novel by Dan Brown. It is Brown''s second novel to include the character Robert Langdon: the first was his 2000 novel Angels & Demons. The Da Vinci Code follows "symbologist" Robert Langdon and cryptologist Sophie Neveu after a murder in the Louvre Museum in Paris causes them to become involved in a battle between the Priory of Sion and Opus Dei over the possibility of Jesus Christ and Mary Magdalene having had a child together.', 'https://covers.openlibrary.org/b/id/13769179-M.jpg'),
    ('9780679745587', 'In Cold Blood', 'Truman Capote', 'Vintage', 1966, 1, 'Mystery', 'On November 15, 1959, in the small town of Holcomb, Kansas, four members of the Clutter family were savagely murdered by blasts from a shotgun held a few inches from their faces. There was no apparent motive for the crime, and there were almost no clues.', 'https://covers.openlibrary.org/b/id/15206099-M.jpg'),
    ('9780140623871', 'The Moonstone', 'Wilkie Collins', 'Penguin', 1868, 3, 'Mystery', 'One of the first English detective novels, this mystery involves the disappearance of a valuable diamond, originally stolen from a Hindu idol, given to a young woman on her eighteenth birthday, and then stolen again. A classic of 19th-century literature.', 'https://covers.openlibrary.org/b/id/13855168-M.jpg'),
    ('9780349019253', 'Rebecca', 'Daphne du Maurier', 'Little, Brown Book Group Limited', 1938, 2, 'Mystery', 'With these words, the reader is ushered into an isolated gray stone mansion on the windswept Cornish coast, as the second Mrs. Maxim de Winter recalls the chilling events that transpired as she began her new life as the young bride of a husband she barely knew. For in every corner of every room were phantoms of a time dead but not forgotten—a past devotedly preserved by the sinister housekeeper, Mrs. Danvers: a suite immaculate and untouched, clothing laid out and ready to be worn, but not by any of the great house''s current occupants. With an eerie presentiment of evil tightening her heart, the second Mrs. de Winter walked in the shadow of her mysterious predecessor, determined to uncover the darkest secrets and shattering truths about Maxim''s first wife—the late and hauntingly beautiful Rebecca.', 'https://covers.openlibrary.org/b/id/15204748-M.jpg'),
    ('9780099283782', 'The Talented Mr. Ripley', 'Patricia Highsmith', 'Vintage', 1955, 4, 'Mystery', 'The first of the acclaimed Ripley novels, this clever psychological thriller introduces the reader to Tom Ripley and his extraordinary modus operandi. Accepting a commission from a wealthy businessman to travel to Italy in an attempt to convince his wayward son to return to the United States, Ripley gradually develops a plan to assume the young man’s identity along with his bank account.', 'https://covers.openlibrary.org/b/id/71833-M.jpg'),
    ('9782261402427', 'Moby-Dick', 'Herman Melville', 'ROUGE & OR', 1851, 4, 'Classics', '"Command the murderous chalices! Drink ye harpooners! Drink and swear, ye men that man the deathful whaleboat''s bow -- Death to Moby Dick!" So Captain Ahab binds his crew to fulfil his obsession -- the destruction of the great white whale. Under his lordly but maniacal command the Pequod''s commercial mission is perverted to one of vengeance. To Ahab, the monster that destroyed his body is not a creature, but the symbol of "some unknown but still reasoning thing." Uncowed by natural disasters, ill omens, even death, Ahab urges his ship towards "the undeliverable, nameless perils of the whale."', 'https://covers.openlibrary.org/b/id/14597625-M.jpg'),
    ('9783895086908', 'War and Peace', 'Leo Tolstoy', 'Konemann', 1869, 1, 'Classics', 'War and Peace delineates in graphic detail events surrounding the French invasion of Russia, and the impact of the Napoleonic era on Tsarist society, as seen through the eyes of five Russian aristocratic families. The novel begins in the year 1805 during the reign of Tsar Alexander I and leads up to the 1812 French invasion of Russia by Napoleon. The era of Catherine the Great (1762–1796), when the royal court in Paris was the centre of western European civilization,[16] is still fresh in the minds of older people. Catherine, fluent in French and wishing to reshape Russia into a great European nation, made French the language of her royal court. For the next one hundred years, it became a social requirement for members of the Russian nobility to speak French and understand French culture.[16] This historical and cultural context in the aristocracy is reflected in War and Peace.', 'https://covers.openlibrary.org/b/id/1036022-M.jpg'),
    ('9781800603806', 'Crime and Punishment', 'Fyodor Dostoevsky', 'Barclays Public Books', 1866, 3, 'Classics', 'A poor former student in St Petersburg murders a pawnbroker to prove he stands above morality, and is slowly undone by guilt and a patient investigator.', 'https://covers.openlibrary.org/b/id/15183762-M.jpg'),
    ('9780451511546', 'The Brothers Karamazov', 'Fyodor Dostoevsky', 'Penguin Publishing Group', 1880, 2, 'Classics', 'Three brothers and their dissolute father in a provincial Russian town: a murder, a trial and Dostoevsky''s deepest questions about faith, doubt and free will.', 'https://covers.openlibrary.org/b/id/13909201-M.jpg'),
    ('9798458501644', 'Don Quixote', 'Miguel de Cervantes', 'Independently Published', 1605, 1, 'Classics', 'An ageing Spanish gentleman reads so many tales of chivalry that he sets out as a knight-errant with his squire Sancho Panza, tilting at windmills.', NULL),
    ('9781405880350', 'Great Expectations', 'Charles Dickens', 'Pearson', 1861, 0, 'Classics', 'Great Expectations is the thirteenth novel by Charles Dickens and his penultimate completed novel. It depicts the education of an orphan nicknamed Pip (the book is a bildungsroman; a coming-of-age story). It is Dickens'' second novel, after David Copperfield, to be fully narrated in the first person. The novel was first published as a serial in Dickens''s weekly periodical All the Year Round, from 1 December 1860 to August 1861. In October 1861, Chapman and Hall published the novel in three volumes. The novel is set in Kent and London in the early to mid-19th century and contains some of Dickens''s most celebrated scenes, starting in a graveyard, where the young Pip is accosted by the escaped convict Abel Magwitch.', 'https://covers.openlibrary.org/b/id/12109249-M.jpg'),
    ('9781398805477', 'The Great Gatsby', 'F. Scott Fitzgerald', 'Arcturus', 1925, 2, 'Classics', 'Here is a novel, glamorous, ironical, compassionate – a marvelous fusion into unity of the curious incongruities of the life of the period – which reveals a hero like no other – one who could live at no other time and in no other place. But he will live as a character, we surmise, as long as the memory of any reader lasts. "There was something gorgeous about him, some heightened sensitivity to the promises of life.... It was an extraordinary gift for hope, a romantic readiness such as I have never found in any other person and which it is not likely I shall ever find again." It is the story of this Jay Gatsby who came so mysteriously to West Egg, of his sumptuous entertainments, and of his love for Daisy Buchanan – a story that ranges from pure lyrical beauty to sheer brutal realism, and is infused with a sense of the strangeness of human circumstance in a heedless universe.', 'https://covers.openlibrary.org/b/id/15144216-M.jpg'),
    ('9780099549482', 'To Kill a Mockingbird', 'Harper Lee', 'Penguin', 1960, 0, 'Classics', 'One of the best-loved stories of all time, To Kill a Mockingbird has been translated into more than 40 languages, sold more than 30 million copies worldwide, served as the basis for an enormously popular motion picture, and voted one of the best novels of the 20th century by librarians across the United States. A gripping, heart-wrenching, and wholly remarkable tale of coming-of-age in a South poisoned by virulent prejudice, it views a world of great beauty and savage inequities through the eyes of a young girl, as her father -- a crusading local lawyer -- risks everything to defend a black man unjustly accused of a terrible crime. Lawyer Atticus Finch defends Tom Robinson -- a black man charged with the rape of a white girl.', 'https://covers.openlibrary.org/b/id/15222699-M.jpg'),
    ('9780141032436', 'One Hundred Years of Solitude', 'Gabriel García Márquez', 'Penguin Books, Limited', 1967, 2, 'Classics', 'One of the twentieth century’s enduring works, One Hundred Years of Solitude is a widely beloved and acclaimed novel known throughout the world and the ultimate achievement in a Nobel Prize–winning career. The novel tells the story of the Buendia family, set against the background of the evolution and eventual decadence of a small South American town, the mythical town of Macondo.', NULL),
    ('9780822070382', 'The Catcher in the Rye', 'J. D. Salinger', 'Wiley & Sons, Incorporated, John', 1951, 0, 'Classics', 'Story of Holden Caufield with his idiosyncrasies, penetrating insight, confusion, sensitivity and negativism. Holden, knowing he is to be expelled from school, decides to leave early. He spends three days in New York City and tells the story of what he did and suffered there.', 'https://covers.openlibrary.org/b/id/14813239-M.jpg'),
    ('9780988744219', 'Ulysses', 'James Joyce', 'Darkening Crows Publishing', 1922, 2, 'Classics', 'Written over a seven-year period, from 1914 to 1921, this book has survived bowdlerization, legal action and controversy. The novel deals with the events of one day in Dublin, 16th June 1904, now known as "Bloomsday". The principal characters are Stephen Dedalus, Leopold Bloom and his wife Molly. Ulysses has been labelled dirty, blasphemous and unreadable. In a famous 1933 court decision, Judge John M. Woolsey declared it an emetic book-although he found it not quite obscene enough to disallow its importation into the United States-and Virginia Woolf was moved to decry James Joyce''s "cloacal obsession". None of these descriptions, however, do the slightest justice to the novel. To this day it remains the modernist masterpiece, in which the author takes both Celtic lyricism and vulgarity to splendid extremes. It is funny, sorrowful, and even (in its own way) suspenseful.', 'https://covers.openlibrary.org/b/id/13136659-M.jpg'),
    ('9780141392608', 'Les Misérables', 'Victor Hugo', 'Penguin Books', 1862, 2, 'Classics', 'In this story of the trials of the peasant Jean Valjean--a man unjustly imprisoned, baffled by destiny, and hounded by his nemesis, the magnificently realized, ambiguously malevolent police detective Javert--Hugo achieves the sort of rare imaginative resonance that allows a work of art to transcend its genre.', 'https://covers.openlibrary.org/b/id/12722874-M.jpg'),
    ('9781299571976', 'The Doll', 'Bolesław Prus', 'New York Review of Books, Incorporated, The', 1890, 1, 'Classics', 'In 1870s Warsaw the self-made merchant Stanisław Wokulski ruins himself for the love of an aristocrat, in a panorama of a society torn between old and new.', 'https://covers.openlibrary.org/b/id/8480256-M.jpg'),
    ('9780781807630', 'Quo Vadis', 'Henryk Sienkiewicz', 'Hippocrene Books, Incorporated', 1896, 2, 'Classics', 'Nero''s insanity threatens the woman of one man''s dreams and all of Roman Christianity. As princess of a now vanquished kingdom, the lovely Lygia lives a hostage in first-century Rome. As an arrogant nobleman accustomed to getting his way, Vinicius decides he will have this strikingly beautiful young woman. But the princess''s deep Christian faith rattles the pagan Vinicius -- who first tries to take her by force, then determines to woo her to himself. As Vinicius pursues Lygia, her behavior and that of Rome''s entire Christian community -- their love, compassion, and forgiveness -- begin to stir his cold, selfish heart. Soon, Emperor Nero steps up his persecution of the Christians, inventing hideous ways of eliminating these people who dare to reject his claims of deity.', 'https://covers.openlibrary.org/b/id/12737769-M.jpg'),
    ('9781400344185', 'Dracula', 'Bram Stoker', 'Harper Muse, an imprint of HarperCollins Focus, LLC', 1897, 0, 'Horror', 'In the story, a couple and their friends are tormented by Count Dracula—a supernatural, blood-drinking entity bound by a contagious curse—who intends to leave his secluded castle in Transylvania for the bustling London of the 19th century. With the help of Professor Van Helsing, the group sets out to confront the undead, despite all the dangers such an offensive will entail.', 'https://covers.openlibrary.org/b/id/15266774-M.jpg'),
    ('9781774530511', 'Frankenstein', 'Mary Shelley', 'Rakuten Kobo', 1818, 1, 'Horror', 'Frankenstein; or, The Modern Prometheus is an 1818 novel written by English author Mary Shelley. Frankenstein tells the story of Victor Frankenstein, a young scientist who creates a sapient creature in an unorthodox scientific experiment. Shelley started writing the story when she was 18, and the first edition was published anonymously in London on 1 January 1818, when she was 20. Her name first appeared in the second edition, which was published in Paris in 1821.', 'https://covers.openlibrary.org/b/id/15148535-M.jpg'),
    ('9781848940994', 'The Shining', 'Stephen King', 'Hodder & Stoughton', 1977, 4, 'Horror', 'The Shining is a 1977 horror novel by American author Stephen King. It is King''s third published novel and first hardback bestseller; its success firmly established King as a preeminent author in the horror genre. The setting and characters are influenced by King''s personal experiences, including both his visit to The Stanley Hotel in 1974 and his struggle with alcoholism. The book was followed by a sequel, Doctor Sleep, published in 2013. The Shining centers on the life of Jack Torrance, a struggling writer and recovering alcoholic who accepts a position as the off-season caretaker of the historic Overlook Hotel in the Colorado Rockies. His family accompanies him on this job, including his young son Danny Torrance, who possesses "the shining", an array of psychic abilities that allow Danny to see the hotel''s horrific past.', 'https://covers.openlibrary.org/b/id/14817043-M.jpg'),
    ('9781444707861', 'It', 'Stephen King', 'Hodder & Stoughton', 1986, 4, 'Horror', '"It" is a 1986 horror novel by American author Stephen King. "It" was his 22nd book and his 17th novel written under his own name. The story follows the experiences of seven children as they are terrorized by an evil entity that exploits the fears of its victims to disguise itself while hunting its prey. "It" primarily appears in the form of Pennywise the Dancing Clown to attract its preferred prey of young children. The novel won the British Fantasy Award in 1987, and received nominations for the Locus and World Fantasy Awards that same year. In 2003, "It" was listed at number 144 on the BBC''s The Big Read poll.', 'https://covers.openlibrary.org/b/id/15255912-M.jpg'),
    ('9780525616801', 'Carrie', 'Stephen King', 'Doubleday', 1974, 1, 'Horror', 'The story of misfit high-school girl, Carrie White, who gradually discovers that she has telekinetic powers. Repressed by a domineering, ultra-religious mother and tormented by her peers at school, her efforts to fit in lead to a dramatic confrontation during the senior prom.', 'https://covers.openlibrary.org/b/id/15140534-M.jpg'),
    ('9781668075760', 'Pet Sematary', 'Stephen King', 'Scribner', 1983, 4, 'Horror', 'Pet Sematary is a 1983 horror novel by American writer Stephen King. The novel was nominated for a World Fantasy Award for Best Novel in 1986', 'https://covers.openlibrary.org/b/id/15166635-M.jpg'),
    ('9780891906223', 'The Haunting of Hill House', 'Shirley Jackson', 'Amereon Ltd', 1959, 0, 'Horror', 'First published in 1959, Shirley Jackson''s The Haunting of Hill House has been hailed as a perfect work of unnerving terror. It is the story of four seekers who arrive at a notoriously unfriendly pile called Hill House: Dr. Montague, an occult scholar looking for solid evidence of a "haunting"; Theodora, his lighthearted assistant; Eleanor, a friendless, fragile young woman well acquainted with poltergeists; and Luke, the future heir of Hill House. At first, their stay seems destined to be merely a spooky encounter with inexplicable phenomena. But Hill House is gathering its powers— and soon, it will choose one of them to make its own.', 'https://covers.openlibrary.org/b/id/13535551-M.jpg'),
    ('9780552176460', 'The Exorcist', 'William Peter Blatty', 'Corgi Books', 1971, 1, 'Horror', 'The Exorcist is a 1971 horror novel by American writer William Peter Blatty. The book details the demonic possession of eleven-year-old Regan MacNeil, the daughter of a famous actress, and the two priests who attempt to exorcise the demon. Published by Harper & Row, the novel was the basis of a highly successful film adaptation released two years later, whose screenplay was also written and produced by Blatty, and part of The Exorcist franchise. The novel was inspired by a 1949 case of demonic possession and exorcism that Blatty heard about while he was a student in the class of 1950 at Georgetown University. As a result, the novel takes place in Washington, D.C., near the campus of Georgetown University.', 'https://covers.openlibrary.org/b/id/14408200-M.jpg'),
    ('9781480465770', 'Rosemary''s Baby', 'Ira Levin', 'Open Road Integrated Media, Inc.', 1967, 1, 'Horror', 'A young wife in a Manhattan apartment building begins to suspect that her charming elderly neighbours and her ambitious husband have plans for her unborn child.', NULL),
    ('9781472200686', 'Interview with the Vampire', 'Anne Rice', 'Taylor & Francis Group', 1976, 2, 'Horror', 'This is the story of Louis, as told in his own words, of his journey through mortal and immortal life. Louis recounts how he became a vampire at the hands of the radiant and sinister Lestat and how he became indoctrinated, unwillingly, into the vampire way of life. His story ebbs and flows through the streets of New Orleans, defining crucial moments such as his discovery of the exquisite lost young child Claudia, wanting not to hurt but to comfort her with the last breaths of humanity he has inside. Yet, he makes Claudia a vampire, trapping her womanly passion, will, and intelligence inside the body of a small child. Louis and Claudia form a seemingly unbreakable alliance and even "settle down" for a while in the opulent French Quarter.', 'https://covers.openlibrary.org/b/id/14709151-M.jpg'),
    ('9781727502398', 'Strange Case of Dr Jekyll and Mr Hyde', 'Robert Louis Stevenson', 'CreateSpace Independent Publishing Platform', 1886, 4, 'Horror', 'A London lawyer investigates the link between his respected friend Dr Jekyll and the brutal Edward Hyde, in the classic tale of a divided self.', NULL),
    ('9781400344161', 'The Picture of Dorian Gray', 'Oscar Wilde', 'Harper Muse, an imprint of HarperCollins Focus LLC', 1890, 1, 'Horror', 'The Picture of Dorian Gray is a philosophical novel by Irish writer Oscar Wilde. A shorter novella-length version was published in the July 1890 issue of the American periodical Lippincott’s Monthly Magazine. The novel-length version was published in April 1891.', 'https://covers.openlibrary.org/b/id/15265884-M.jpg'),
    ('9781483004365', 'Bird Box', 'Josh Malerman', 'Harpercollins', 2014, 2, 'Horror', 'In an apocalyptic near-future world, a mother and her two small children are followed as they make their way down a river, blindfolded, in order to avoid seeing a terrifying entity. The plot contains profanity and graphic violence.', 'https://covers.openlibrary.org/b/id/11185546-M.jpg'),
    ('9781529943993', 'House of Leaves', 'Mark Z. Danielewski', 'Transworld Publishers Limited', 2000, 1, 'Horror', 'A young family moves into a small home on Ash Tree Lane where they discover something is terribly wrong: their house is bigger on the inside than it is on the outside. Of course, neither Pulitzer Prize-winning photojournalist Will Navidson nor his companion Karen Green was prepared to face the consequences of that impossibility, until the day their two little children wandered off and their voices eerily began to return another story—of creature darkness, of an ever-growing abyss behind a closet door, and of that unholy growl which soon enough would tear through their walls and consume all their dreams.', 'https://covers.openlibrary.org/b/id/15201835-M.jpg'),
    ('9780715653739', 'World War Z', 'Max Brooks', 'Duckworth', 2006, 1, 'Horror', '“The end was near.” —Voices from the Zombie War The Zombie War came unthinkably close to eradicating humanity. Max Brooks, driven by the urgency of preserving the acid-etched first-hand experiences of the survivors from those apocalyptic years, traveled across the United States of America and throughout the world, from decimated cities that once teemed with upwards of thirty million souls to the most remote and inhospitable areas of the planet. He recorded the testimony of men, women, and sometimes children who came face-to-face with the living, or at least the undead, hell of that dreadful time. World War Z is the result. Never before have we had access to a document that so powerfully conveys the depth of fear and horror, and also the ineradicable spirit of resistance, that gripped human society through the plague years.', 'https://covers.openlibrary.org/b/id/14799147-M.jpg'),
    ('9781648337093', 'Pride and Prejudice', 'Jane Austen', 'Page Publications', 1813, 1, 'Romance', 'Pride and Prejudice is an 1813 novel of manners written by Jane Austen. The novel follows the character development of Elizabeth Bennet, the dynamic protagonist of the book who learns about the repercussions of hasty judgments and comes to appreciate the difference between superficial goodness and actual goodness. Mr. Bennet, owner of the Longbourn estate in Hertfordshire, has five daughters, but his property is entailed and can only be passed to a male heir. His wife also lacks an inheritance, so his family faces becoming very poor upon his death. Thus, it is imperative that at least one of the girls marry well to support the others, which is a motivation that drives the plot.', 'https://covers.openlibrary.org/b/id/14665299-M.jpg'),
    ('9780141439662', 'Sense and Sensibility', 'Jane Austen', 'Penguin Classics', 1811, 2, 'Romance', 'When Mr. Dashwood dies, he must leave the bulk of his estate to the son by his first marriage, which leaves his second wife and three daughters (Elinor, Marianne, and Margaret) in straitened circumstances. They are taken in by a kindly cousin, but their lack of fortune affects the marriageability of both practical Elinor and romantic Marianne. When Elinor forms an attachment for the wealthy Edward Ferrars, his family disapproves and separates them. And though Mrs. Jennings tries to match the worthy (and rich) Colonel Brandon to her, Marianne finds the dashing and fiery Willoughby more to her taste. Both relationships are sorely tried. But this is a romance, and through the hardships and heartbreak, true love and a happy ending will find their way for both the sister who is all sense and the one who is all sensibility. - Publisher.', 'https://covers.openlibrary.org/b/id/15264376-M.jpg'),
    ('9780141199528', 'Emma', 'Jane Austen', 'Penguin English Library', 1815, 4, 'Romance', 'Emma, by Jane Austen, is a novel about youthful hubris and the perils of misconstrued romance. The novel was first published in December 1815. As in her other novels, Austen explores the concerns and difficulties of genteel women living in Georgian-Regency England; she also creates a lively comedy of manners among her characters. Before she began the novel, Austen wrote, "I am going to take a heroine whom no one but myself will much like." In the very first sentence she introduces the title character as "Emma Woodhouse, handsome, clever, and rich." Emma, however, is also rather spoiled, headstrong, and self-satisfied; she greatly overestimates her own matchmaking abilities; she is blind to the dangers of meddling in other people''s lives; and her imagination and perceptions often lead her astray.', 'https://covers.openlibrary.org/b/id/15101895-M.jpg'),
    ('9780451512734', 'Persuasion', 'Jane Austen', 'Penguin Publishing Group', 1817, 1, 'Romance', 'Persuasion tells the love story of Anne Elliot and Captain Frederick Wentworth, whose sister rents Miss Elliot''s father''s house, after the Napoleonic Wars come to an end. The story is set in 1814. The book itself is Jane Austen''s last published book, published posthumously in December of 1818.', 'https://covers.openlibrary.org/b/id/13274676-M.jpg'),
    ('9780582096707', 'Jane Eyre', 'Charlotte Brontë', 'Addison-Wesley Longman, Limited', 1847, 2, 'Romance', 'The novel is set somewhere in the north of England. Jane''s childhood at Gateshead Hall, where she is emotionally and physically abused by her aunt and cousins; her education at Lowood School, where she acquires friends and role models but also suffers privations and oppression; her time as the governess of Thornfield Hall, where she falls in love with her Byronic employer, Edward Rochester; her time with the Rivers family, during which her earnest but cold clergyman cousin, St John Rivers, proposes to her. Will she or will she not marry him?', 'https://covers.openlibrary.org/b/id/15164202-M.jpg'),
    ('9798542843742', 'Wuthering Heights', 'Emily Brontë', 'RAS Publishing', 1847, 0, 'Romance', 'Wuthering Heights is an 1847 novel by Emily Brontë, initially published under the pseudonym Ellis Bell. It concerns two families of the landed gentry living on the West Yorkshire moors, the Earnshaws and the Lintons, and their turbulent relationships with Earnshaw''s adopted son, Heathcliff. The novel was influenced by Romanticism and Gothic fiction.', 'https://covers.openlibrary.org/b/id/14840570-M.jpg'),
    ('9781440788512', 'Outlander', 'Diana Gabaldon', 'Recorded Books', 1991, 0, 'Romance', 'Unrivaled storytelling. Unforgettable characters. Rich historical detail. These are the hallmarks of Diana Gabaldon’s work. Her New York Times bestselling Outlander novels have earned the praise of critics and captured the hearts of millions of fans. Here is the story that started it all, introducing two remarkable characters, Claire Beauchamp Randall and Jamie Fraser, in a spellbinding novel of passion and history that combines exhilarating adventure with a love story for the ages. One of the top ten best-loved novels in America, as seen on PBS’s The Great American Read! Scottish Highlands, 1945. Claire Randall, a former British combat nurse, is just back from the war and reunited with her husband on a second honeymoon when she walks through a standing stone in one of the ancient circles that dot the British Isles.', 'https://covers.openlibrary.org/b/id/12000557-M.jpg'),
    ('9780751547498', 'The Notebook', 'Nicholas Sparks', 'Little, Brown Book Group Limited', 1996, 2, 'Romance', 'A man with a faded, well-worn notebook open in his lap. A woman experiencing a morning ritual she doesn''t understand. Until he begins to read to her. An achingly tender story about the enduring power of love. A man with a faded, well-worn notebook open in his lap. A woman experiencing a morning ritual she doesn''t understand. Until he begins to read to her. The Notebook is an achingly tender story about the enduring power of love, a story of miracles that will stay with you forever. Set amid the austere beauty of coastal North Carolina in 1946, The Notebook begins with the story of Noah Calhoun, a rural Southerner returned home from World War II. Noah, thirty-one, is restoring a plantation home to its former glory, and he is haunted by images of the beautiful girl he met fourteen years earlier, a girl he loved like no other.', 'https://covers.openlibrary.org/b/id/13856370-M.jpg'),
    ('9780670026609', 'Me Before You', 'Jojo Moyes', 'Pamela Dorman Books', 2012, 1, 'Romance', 'Louisa Clark is an ordinary young woman living an exceedingly ordinary life—steady boyfriend, close family—who has never been farther afield than their tiny village. She takes a badly needed job working for ex-Master of the Universe Will Traynor, who is wheelchair-bound after an accident. Will has always lived a huge life—big deals, extreme sports, worldwide travel—and now he’s pretty sure he cannot live the way he is. Will is acerbic, moody, bossy—but Lou refuses to treat him with kid gloves, and soon his happiness means more to her than she expected. When she learns that Will has shocking plans of his own, she sets out to show him that life is still worth living.', 'https://covers.openlibrary.org/b/id/15222783-M.jpg'),
    ('9781785417290', 'Normal People', 'Sally Rooney', 'ISIS', 2018, 3, 'Romance', 'At school Connell and Marianne pretend not to know each other. He’s popular and well-adjusted, star of the school soccer team while she is lonely, proud, and intensely private. But when Connell comes to pick his mother up from her housekeeping job at Marianne’s house, a strange and indelible connection grows between the two teenagers - one they are determined to conceal. A year later, they’re both studying at Trinity College in Dublin. Marianne has found her feet in a new social world while Connell hangs at the sidelines, shy and uncertain. Throughout their years in college, Marianne and Connell circle one another, straying toward other people and possibilities but always magnetically, irresistibly drawn back together. Then, as she veers into self-destruction and he begins to search for meaning elsewhere, each must confront how far they are willing to go to save the other.', 'https://covers.openlibrary.org/b/id/15213474-M.jpg'),
    ('9781665154567', 'The Time Traveler''s Wife', 'Audrey Niffenegger', 'Highbridge Audio and Blackstone Publishing', 2003, 4, 'Romance', 'Audrey Niffenegger''s innovative debut, The Time Traveler''s Wife, is the story of Clare, a beautiful art student, and Henry, an adventuresome librarian, who have known each other since Clare was six and Henry was thirty-six, and were married when Clare was twenty-three and Henry thirty-one. Impossible but true, because Henry is one of the first people diagnosed with Chrono-Displacement Disorder: periodically his genetic clock resets and he finds himself misplaced in time, pulled to moments of emotional gravity in his life, past and future. His disappearances are spontaneous, his experiences unpredictable, alternately harrowing and amusing.', 'https://covers.openlibrary.org/b/id/12231830-M.jpg'),
    ('9780670068791', 'Gone with the Wind', 'Margaret Mitchell', 'Indigo Library', 1936, 0, 'Romance', 'Margaret Mitchell''s monumental epic of the South won a Pulitzer Prize, gave rise to the most popular motion picture of our time, and inspired a sequel that became the fastest selling novel of the century. It is one of the most popular books ever written: more than 28 million copies of the book have been sold in more than 37 countries. Today, more than 60 years after its initial publication, its achievements are unparalleled, and it remains the most revered American saga and the most beloved work by an American writer...', 'https://covers.openlibrary.org/b/id/15243829-M.jpg'),
    ('9781636379944', 'Doctor Zhivago', 'Boris Pasternak', 'Bibliotech Press', 1957, 4, 'Romance', 'A physician and poet lives through the Russian Revolution and civil war, torn between his wife and his love for Lara.', NULL),
    ('9781402511783', 'Atonement', 'Ian McEwan', 'Brand: Recorded Books', 2001, 1, 'Romance', 'Atonement is a 2001 British metafiction novel written by Ian McEwan. Set in three time periods, 1935 England, Second World War England and France, and present-day England, it covers an upper-class girl''s half-innocent mistake that ruins lives, her adulthood in the shadow of that mistake, and a reflection on the nature of writing. Widely regarded as one of McEwan''s best works, it was shortlisted for the 2001 Booker Prize for fiction. In 2010, Time magazine named Atonement in its list of the 100 greatest English-language novels since 1923.', 'https://covers.openlibrary.org/b/id/13537200-M.jpg'),
    ('9798532139442', 'North and South', 'Elizabeth Gaskell', 'Independently Published', 1855, 3, 'Romance', 'Margaret Hale moves from the rural south of England to an industrial northern town and clashes with the mill owner John Thornton over workers'' rights, and over love.', NULL),
    ('9780547338002', 'The Little Prince', 'Antoine de Saint-Exupéry', 'Clarion Books', 1943, 2, 'Children''s', 'A pilot stranded in the Sahara meets a little prince from a tiny asteroid, whose travels among strange grown-ups show that what matters most is invisible to the eye.', 'https://covers.openlibrary.org/b/id/11555254-M.jpg'),
    ('9780739374511', 'Charlotte''s Web', 'E. B. White', 'Random House', 1952, 2, 'Children''s', 'Charlotte''s Web is a book of children''s literature by American author E. B. White and illustrated by Garth Williams; it was published on October 15, 1952, by Harper & Brothers. The novel tells the story of a livestock pig named Wilbur and his friendship with a barn spider named Charlotte. When Wilbur is in danger of being slaughtered by the farmer, Charlotte writes messages praising Wilbur (such as "Some Pig") in her web in order to persuade the farmer to let him live.', 'https://covers.openlibrary.org/b/id/13778183-M.jpg'),
    ('9780224070966', 'Matilda', 'Roald Dahl', 'Jonathan Cape', 1988, 2, 'Children''s', 'Matilda applies her untapped mental powers to rid the school of the evil, child-hating headmistress, Miss Trunchbull, and restore her nice teacher, Miss Honey, to financial security.', 'https://covers.openlibrary.org/b/id/12895022-M.jpg'),
    ('9780593886779', 'Charlie and the Chocolate Factory', 'Roald Dahl', 'Penguin Young Readers Group', 1964, 1, 'Children''s', 'Charlie and the Chocolate Factory is a 1964 children''s novel by British author Roald Dahl. The story features the adventures of young Charlie Bucket inside the chocolate factory of eccentric chocolatier Willy Wonka. Charlie and the Chocolate Factory was first published in the United States by Alfred A. Knopf, Inc. in 1964 and in the United Kingdom by George Allen & Unwin 11 months later. In the 2012 survey published by SLJ, a monthly with primarily US audience, Charlie was the second of four books by Dahl among their Top 100 Chapter Books, one more than any other writer. Time magazine in the US included the novel in its list of the 100 Best Young-Adult Books of All Time.', 'https://covers.openlibrary.org/b/id/14653686-M.jpg'),
    ('9780007635665', 'The Lion, the Witch and the Wardrobe', 'C. S. Lewis', 'Collier Books', 1950, 4, 'Children''s', 'Four adventurous siblings—Peter, Susan, Edmund, and Lucy Pevensie—step through a wardrobe door and into the land of Narnia, a land frozen in eternal winter and enslaved by the power of the White Witch. But when almost all hope is lost, the return of the Great Lion, Aslan, signals a great change . . . and a great sacrifice. Journey into the land beyond the wardrobe! The Lion, the Witch and the Wardrobe is the second book in C. S. Lewis''s classic fantasy series, which has been captivating readers of all ages for over sixty years. This is a stand-alone novel, but if you would like journey back to Narnia, read The Horse and His Boy, the third book in The Chronicles of Narnia.', 'https://covers.openlibrary.org/b/id/13162582-M.jpg'),
    ('9780575032637', 'Alice''s Adventures in Wonderland', 'Lewis Carroll', 'Gollancz', 1865, 1, 'Children''s', 'Alice''s Adventures in Wonderland (commonly Alice in Wonderland) is an 1865 English children''s novel by Lewis Carroll. A young girl named Alice falls through a rabbit hole into a fantasy world of anthropomorphic creatures. It is seen as an example of the literary nonsense genre. One of the best-known works of Victorian literature, its narrative, structure, characters and imagery have had huge influence on popular culture and literature, especially in the fantasy genre.', 'https://covers.openlibrary.org/b/id/14572004-M.jpg'),
    ('9780755500550', 'Winnie-the-Pooh', 'A. A. Milne', 'Egmont Books, Limited', 1926, 0, 'Children''s', 'A.A. Milne''s Pooh stories need no introduction; they have been loved by generations of children and their parents ever since they were first published in 1926. In his autobiography, Milne wrote: ''The animals in the stories came for the most part from the nursery. My collaborator [his wife] had already given them individual voices, their owner by constant affection had given them the twist in their features which denotes character, and Shepard drew them, as one might say, from the living model.''', 'https://covers.openlibrary.org/b/id/13311334-M.jpg'),
    ('9780956613660', 'Peter Pan', 'J. M. Barrie', 'Merchiston Publishing', 1911, 0, 'Children''s', 'The adventures of the three Darling children in Never-Never Land with Peter Pan, the boy who would not grow up.', 'https://covers.openlibrary.org/b/id/12692857-M.jpg'),
    ('9781631403439', 'The Wind in the Willows', 'Kenneth Grahame', 'IDW Publishing', 1908, 0, 'Children''s', 'Mole, Rat, Badger and the reckless, motor-car-mad Toad share friendship and adventures along an English river.', 'https://covers.openlibrary.org/b/id/11472712-M.jpg'),
    ('9781246920758', 'Treasure Island', 'Robert Louis Stevenson', 'Creative Media Partners, LLC', 1883, 2, 'Children''s', 'Traditionally considered a coming-of-age story, Treasure Island is an adventure tale known for its atmosphere, characters and action, and also as a wry commentary on the ambiguity of morality — as seen in Long John Silver — unusual for children''s literature then and now. It is one of the most frequently dramatized of all novels. The influence of Treasure Island on popular perceptions of pirates is enormous, including treasure maps marked with an "X", schooners, the Black Spot, tropical islands, and one-legged seamen carrying parrots on their shoulders', 'https://covers.openlibrary.org/b/id/13845173-M.jpg'),
    ('9781403710062', 'The Adventures of Tom Sawyer', 'Mark Twain', 'Dalmatian Press', 1876, 4, 'Children''s', 'Mark Twain created the memorable characters Tom Sawyer and Huckleberry Finn drawing from the experiences of boys he grew up with in Missouri. Set by the Mississippi River in the 1840''s, it follows these boys as they get into predicament after predicament. Tom''s classic whitewashing of the fence has become part of American legend, and the book paints a nostalgic picture of life in the middle of the nineteenth century. Tom runs away from home to an island in the river, chases Injun Joe and his treasure, and even gets trapped in a cave for days with Becky Thatcher. The book is one of Twain''s most beloved stories.', 'https://covers.openlibrary.org/b/id/15165870-M.jpg'),
    ('9781909438972', 'Anne of Green Gables', 'L. M. Montgomery', 'Bollinger, Max', 1908, 1, 'Children''s', 'Anne, an eleven-year-old orphan, is sent by mistake to live with a lonely, middle-aged brother and sister on a Prince Edward Island farm and proceeds to make an indelible impression on everyone around her.', 'https://covers.openlibrary.org/b/id/14663473-M.jpg'),
    ('9781406844955', 'The Secret Garden', 'Frances Hodgson Burnett', 'Echo Library', 1911, 2, 'Children''s', 'A ten-year-old orphan comes to live in a lonely house on the Yorkshire moors where she discovers an invalid cousin and the mysteries of a locked garden.', 'https://covers.openlibrary.org/b/id/13623921-M.jpg'),
    ('9798855077346', 'Pippi Longstocking', 'Astrid Lindgren', 'Bound to Stay Bound Books', 1945, 2, 'Children''s', 'The strongest girl in the world lives alone with a horse and a monkey, without any rules, and turns her small Swedish town upside down.', NULL),
    ('9780439244190', 'Holes', 'Louis Sachar', 'Yearling', 1998, 0, 'Children''s', 'Stanley Yelnats is under a curse. A curse that began with his no-good-dirty-rotten-pig-stealing great-great-grandfather and has since followed generations of Yelnatses. Now Stanley has been unjustly sent to a boys'' detention center, Camp Green Lake, where the boys build character by spending all day, every day, digging holes exactly five feet wide and five feet deep. There is no lake at Camp Green Lake. But there are an awful lot of holes. It doesn''t take long for Stanley to realize that Camp Green Lake isn''t what it seems. Are the boys digging holes because the warden is looking for something? But what could be buried under a dried-up lake? It''s up to Stanley to dig up the truth.', 'https://covers.openlibrary.org/b/id/15122371-M.jpg'),
    ('9780771038747', 'Sapiens', 'Yuval Noah Harari', 'McClelland & Stewart', 2011, 0, 'History', 'From a renowned historian comes a groundbreaking narrative of humanity’s creation and evolution—a #1 international bestseller—that explores the ways in which biology and history have defined us and enhanced our understanding of what it means to be “human.” One hundred thousand years ago, at least six different species of humans inhabited Earth. Yet today there is only one—homo sapiens. What happened to the others? And what may happen to us? Most books about the history of humanity pursue either a historical or a biological approach, but Dr. Yuval Noah Harari breaks the mold with this highly original book that begins about 70,000 years ago with the appearance of modern cognition.', 'https://covers.openlibrary.org/b/id/13775631-M.jpg'),
    ('9780307932426', 'Guns, Germs, and Steel', 'Jared Diamond', 'Random House Audio', 1997, 2, 'History', 'An epic detective story that offers a gripping expose on why the world is so unequal. Professor Jared Diamond traveled the globe for over 30 years trying to answer this question.', 'https://covers.openlibrary.org/b/id/10489489-M.jpg'),
    ('9780141971667', 'The Diary of a Young Girl', 'Anne Frank', 'Penguin Books, Limited', 1947, 0, 'History', 'The Diary of a Young Girl, also known as The Diary of Anne Frank, is a book of the writings from the Dutch-language diary kept by Anne Frank while she was in hiding for two years with her family during the Nazi occupation of the Netherlands. The family was apprehended in 1944, and Anne Frank died of typhus in the Bergen-Belsen concentration camp in 1945. Anne''s diaries were retrieved by Miep Gies and Bep Voskuijl. Miep gave them to Anne''s father, Otto Frank, the family''s only survivor, just after the Second World War was over.', 'https://covers.openlibrary.org/b/id/15087911-M.jpg'),
    ('9781441734211', 'The Rise and Fall of the Third Reich', 'William L. Shirer', 'Blackstone Audiobooks', 1960, 0, 'History', 'Since it''s publication five decades ago, William L. Shirer''s monumental study of Hitler''s empire has been widely acclaimed as the definitive record of the twentieth century''s blackest hours. A worldwide bestseller with millions of copies in print, The Rise and Fall of the Third Reich offers an unparalleled and thrillingly told examination of how Adolf Hitler nearly succeeded in conquering the world. Here, in a thoughtful new introduction for the fiftieth anniversary of its National Book Award win, Ron Rosenbaum, author of the much-admired Explaining Hitler, takes a fresh and penetrating look at this vital and enduring classic and the role it continues to play in today''s discussions of the history of Nazi Germany.', 'https://covers.openlibrary.org/b/id/10840477-M.jpg'),
    ('9781631492228', 'SPQR', 'Mary Beard', 'Liveright Publishing Corporation', 2015, 0, 'History', '"Ancient Rome matters. Its history of empire, conquest, cruelty and excess is something against which we still judge ourselves. Its myths and stories - from Romulus and Remus to the Rape of Lucretia - still strike a chord with us. And its debates about citizenship, security and the rights of the individual still influence our own debates on civil liberty today. SPQR is a new look at Roman history from one of the world''s foremost classicists. It explores not only how Rome grew from an insignificant village in central Italy to a power that controlled territory from Spain to Syria, but also how the Romans thought about themselves and their achievements, and why they are still important to us.', 'https://covers.openlibrary.org/b/id/10382021-M.jpg'),
    ('9780553026696', 'The Guns of August', 'Barbara W. Tuchman', 'Bantam Books', 1962, 1, 'History', 'Published to immediate acclaim in 1962 and the winner of the Pulitzer Prize in 1963, The Guns of August is the classic account of the cataclysmic outbreak of World War I in 1914 and the 30 days of battle that followed. This opening clash determined the future course of the war and shaped the history of our century. Its tense drama continues to enthrall readers of Barbara W. Tuchman''s magnificent best-selling work, now in 25th anniversary edition with a new preface by the author. In the summer of 1914, Europe with a heap of swords piled as delicately as jackstraws, and not one could be drawn out without upsetting the others. Still, statesmen, field marshals, admirals, kings, and patriots believed what they wanted to believe -- or what they feared not to believe -- and waited in profound ignorance for victory to reveal itself within a matter of weeks.', 'https://covers.openlibrary.org/b/id/9899148-M.jpg'),
    ('9780141043722', 'Team of Rivals', 'Doris Kearns Goodwin', 'imusti', 2005, 1, 'History', 'Team of Rivals: The Political Genius of Abraham Lincoln is a 2005 book by Pulitzer Prize-winning American historian Doris Kearns Goodwin, published by Simon & Schuster. The book is a biographical portrait of U.S. President Abraham Lincoln and some of the men who served with him in his cabinet from 1861 to 1865. Three of his Cabinet members had previously run against Lincoln in the 1860 election: Attorney General Edward Bates, Secretary of the Treasury Salmon P. Chase and Secretary of State William H. Seward. The book focuses on Lincoln''s mostly successful attempts to reconcile conflicting personalities and political factions on the path to abolition and victory in the American Civil War. Goodwin''s sixth book, Team of Rivals was well received by critics and won the 2006 Lincoln Prize and the inaugural Book Prize for American History of the New-York Historical Society.', 'https://covers.openlibrary.org/b/id/10641285-M.jpg'),
    ('9781408839997', 'The Silk Roads', 'Peter Frankopan', 'Bloomsbury Publishing', 2015, 1, 'History', '"Our world was made on and by the Silk Roads. For millennia it was here that East and West encountered each other through trade and conquest, leading to the spread of ideas and cultures, the birth of the world''s great religions, the appetites for foreign goods that drove economies and the growth of nations. From the first cities in Mesopotamia to the growth of Greece and Rome to the depredations by the Mongols and the Black Death to the Great Game and the fall of Communism, the fate of the West has always been inextricably linked to the East. The Silk Roads vividly captures the importance of the networks that crisscrossed the spine of Asia and linked the Atlantic with the Pacific, the Mediterranean with India, America with the Persian Gulf.', 'https://covers.openlibrary.org/b/id/15265564-M.jpg'),
    ('9780965607414', 'A People''s History of the United States', 'Howard Zinn', 'harper collins publishers', 1980, 2, 'History', 'Known for its lively, clear prose as well as its scholarly research, A People''s History of the United States is the only volume to tell America''s story from the point of view of -- and in the words of -- America''s women, factory workers, African Americans, Native Americans, working poor, and immigrant laborers.', 'https://covers.openlibrary.org/b/id/15190793-M.jpg'),
    ('9781407075518', 'Bloodlands', 'Timothy Snyder', 'Penguin Random House', 2010, 2, 'History', 'Americans call the Second World War "The Good War." But before it even began, America''s wartime ally Josef Stalin had killed millions of his own citizens -- and kept killing them during and after the war. Before Hitler was finally defeated, he had murdered six million Jews and nearly as many other Europeans. At war''s end, both the German and the Soviet killing sites fell behind the iron curtain, leaving the history of mass killing in darkness.Bloodlands is a new kind of European history, presenting the mass murders committed by the Nazi and Stalinist regimes as two aspects of a single history, in the time and place where they occurred: between Germany and Russia, when Hitler and Stalin both held power. Assiduously researched, deeply humane, and utterly definitive, Bloodlands will be required reading for anyone seeking to understand the central tragedy of modern history. - Publisher.', 'https://covers.openlibrary.org/b/id/14313808-M.jpg'),
    ('9780231053501', 'God''s Playground', 'Norman Davies', 'Columbia University Press', 1981, 1, 'History', 'A history of Poland from its origins to the present: the Polish-Lithuanian Commonwealth, the partitions, the world wars and communism.', 'https://covers.openlibrary.org/b/id/9299298-M.jpg'),
    ('9781441778222', 'Postwar', 'Tony Judt', 'Blackstone Audio, Inc.', 2005, 3, 'History', 'The first truly European history of contemporary Europe, from Lisbon to Leningrad, based on research in six languages, covering 34 countries across 60 years, using a great deal of material from newly available sources. The book integrates international relations, domestic politics, ideas, social change, economic development, and culture--high and low--into a single grand narrative. Every country has its chance to play the lead, and although the big themes are handled--including the cold war, the love/hate relationship with America, cultural and economic malaise and rebirth, and the myth and reality of unification--none of them is allowed to overshadow the rich pageant that is the whole.--From publisher description.', 'https://covers.openlibrary.org/b/id/14264546-M.jpg'),
    ('9780002722803', 'The Gulag Archipelago', 'Aleksandr Solzhenitsyn', 'Collins Harvill', 1973, 1, 'History', 'A history of the Soviet forced-labour camps, built from Solzhenitsyn''s own imprisonment and the testimony of hundreds of former prisoners.', 'https://covers.openlibrary.org/b/id/14385421-M.jpg'),
    ('9781471159114', 'The Wright Brothers', 'David McCullough', 'Simon & Schuster Ltd', 2015, 1, 'History', 'Two-time winner of the Pulitzer Prize David McCullough tells the dramatic story of the courageous brothers who taught the world how to fly. On a winter day in 1903, on the remote Outer Banks of North Carolina, two unknown brothers from Ohio, Wilbur and Orville Wright, changed history. The age of flight had begun with the first heavier-than-air powered machine carrying a pilot. Far more than a couple of Dayton bicycle mechanics who happened to hit on success, the Wright brothers were men of exceptional ability, unyielding determination, and far-ranging intellectual interest and curiosity, much of which they attributed to their upbringing. They grew up without electricity or indoor plumbing, but with books aplenty, supplied mainly by their preacher father. And they never stopped learning.', 'https://covers.openlibrary.org/b/id/14816601-M.jpg'),
    ('9780553380163', 'A Brief History of Time', 'Stephen Hawking', 'andom House Publishing Group', 1988, 0, 'Popular science', 'Stephen Hawking''s ‘A Brief History of Time* has become an international publishing phenomenon. Translated into thirty languages, it has sold over ten million copies worldwide and lives on as a science book that continues to captivate and inspire new readers each year. When it was first published in 1988 the ideas discussed in it were at the cutting edge of what was then known about the universe. In the intervening twenty years there have been extraordinary advances in the technology of observing both the micro- and macro-cosmic world. Indeed, during that time cosmology and the theoretical sciences have entered a new golden age . Professor Hawking is one of the major scientists and thinkers to have contributed to this renaissance.', 'https://covers.openlibrary.org/b/id/14589690-M.jpg'),
    ('9780307291868', 'Cosmos', 'Carl Sagan', 'Carl Sagan Productions, Inc.', 1980, 0, 'Popular science', 'This book is about science in its broadest human context, how science and civilization grew up together. It is the story of our long journey of discovery and the forces and individuals who helped to shape modern science, including Democritus, Hypatia, Kepler, Newton, Huygens, Champollion, Lowell and Humason. The book also explores spacecraft missions of discovery of the nearby planets, the research in the Library of ancient Alexandria, the human brain, Egyptian hieroglyphics, the origin of life, the death of the Sun, the evolution of galaxies and the origins of matter, suns and worlds. The author retraces the fifteen billion years of cosmic evolution that have transformed matter into life and consciousness, enabling the cosmos to wonder about itself. He considers the latest findings on life elsewhere and how we might communicate with the beings of other worlds. ~ WorldCat.org', 'https://covers.openlibrary.org/b/id/14647617-M.jpg'),
    ('9780198985389', 'The Selfish Gene', 'Richard Dawkins', 'Oxford University Press', 1976, 1, 'Popular science', 'As influential today as when it was first published, The Selfish Gene has become a classic exposition of evolutionary thought. Professor Dawkins articulates a gene''s eye view of evolution - a view giving centre stage to these persistent units of information, and in which organisms can be seen as vehicles for their replication. This imaginative, powerful, and stylistically brilliant work not only brought the insights of Neo-Darwinism to a wide audience, but galvanized the biology community, generating much debate and stimulating whole new areas of research. Forty years later, its insights remain as relevant today as on the day it was published. This 40th anniversary edition includes a new epilogue from the author discussing the continuing relevance of these ideas in evolutionary biology today, as well as the original prefaces and foreword, and extracts from early reviews.', 'https://covers.openlibrary.org/b/id/15248606-M.jpg'),
    ('9781508211389', 'The Gene', 'Siddhartha Mukherjee', 'Simon & Schuster Audio', 2016, 2, 'Popular science', 'The Gene: An Intimate History is a book written by Siddhartha Mukherjee, an Indian-born American physician and oncologist. It was published on 17 May 2016 by Scribner. The book chronicles the history of the gene and genetic research, all the way from Aristotle to Crick, Watson and Franklin and then the 21st century scientists who mapped the human genome. The book discusses the power of genetics in determining people''s well-being and traits. It delves into the personal genetic history of Siddhartha Mukherjee''s family, including mental illness. However, it is also a cautionary message toward not letting genetic predispositions define a person or their fate, a mentality that the author says led to the rise of eugenics in history.', 'https://covers.openlibrary.org/b/id/11466863-M.jpg'),
    ('9781116871333', 'On the Origin of Species', 'Charles Darwin', 'BiblioBazaar', 1859, 0, 'Popular science', 'Charles Darwin''s seminal work laying the foundations for the principles of evolutionary biology via natural selection, based on evidence that he collected during his expedition on HMS Beagle in the 1830s.', 'https://covers.openlibrary.org/b/id/6301562-M.jpg'),
    ('9780606269544', 'The Immortal Life of Henrietta Lacks', 'Rebecca Skloot', 'Turtleback', 2010, 4, 'Popular science', 'Her name was Henrietta Lacks, but scientists know her as HeLa. She was a poor black tobacco farmer whose cells—taken without her knowledge in 1951—became one of the most important tools in medicine, vital for developing the polio vaccine, cloning, gene mapping, in vitro fertilization, and more. Henrietta’s cells have been bought and sold by the billions, yet she remains virtually unknown, and her family can’t afford health insurance. This New York Times bestseller takes readers on an extraordinary journey, from the “colored” ward of Johns Hopkins Hospital in the 1950s to stark white laboratories with freezers filled with HeLa cells, from Henrietta’s small, dying hometown of Clover, Virginia, to East Baltimore today, where her children and grandchildren live and struggle with the legacy of her cells.', 'https://covers.openlibrary.org/b/id/10689931-M.jpg'),
    ('9780552997041', 'A Short History of Nearly Everything', 'Bill Bryson', 'Black Swan', 2003, 4, 'Popular science', 'A Short History of Nearly Everything by American author Bill Bryson is a popular science book that explains some areas of science, using easily accessible language that appeals more so to the general public than many other books dedicated to the subject. It was one of the bestselling popular science books of 2005 in the United Kingdom, selling over 300,000 copies. A Short History deviates from Bryson''s popular travel book genre, instead describing general sciences such as chemistry, paleontology, astronomy, and particle physics. In it, he explores time from the Big Bang to the discovery of quantum mechanics, via evolution and geology. Bill Bryson wrote this book because he was dissatisfied with his scientific knowledge—that was, not much at all. He writes that science was a distant, unexplained subject at school.', 'https://covers.openlibrary.org/b/id/15214565-M.jpg'),
    ('9780395166116', 'Silent Spring', 'Rachel Carson', 'Houghton Mifflin Co', 1962, 2, 'Popular science', 'An investigation of how synthetic pesticides such as DDT poison wildlife and people, which launched the modern environmental movement.', 'https://covers.openlibrary.org/b/id/15199104-M.jpg'),
    ('9780393058581', 'The Elegant Universe', 'Brian Greene', 'W. W. Norton & Company', 1999, 2, 'Popular science', 'In this refreshingly clear book, Brian Greene, a leading string theorist, relates the scientific story and the human struggle behind the search for the ultimate theory. String theory, as the author vividly describes, reveals a vision of the universe that is sending shock waves through the world of physics. Thrilling and revolutionary ideas such as new dimensions hidden within the fabric of space, black holes transmuting into elementary particles, rips and punctures in the space-time continuum, gigantic universes interchangeable with minuscule ones, and a wealth of others are playing a pivotal role as physicists use string theory to grapple with some of the deepest questions of the ages.', 'https://covers.openlibrary.org/b/id/247920-M.jpg'),
    ('9781538408001', 'Astrophysics for People in a Hurry', 'Neil deGrasse Tyson', 'Blackstone Publishing', 2017, 1, 'Popular science', 'A short book for almost all ages, it’s simply astrophysics for people in a hurry, taught by acclaimed astrophysicist Neil deGrasse Tyson. This is a must-read for anyone who wants to know how the universe works!', 'https://covers.openlibrary.org/b/id/13225598-M.jpg'),
    ('9780393355628', 'Surely You''re Joking, Mr. Feynman!', 'Richard P. Feynman', 'W. W. Norton & Company', 1985, 2, 'Popular science', 'The biography of the physicist and Nobel prize winner Richard P. Feynman - a collection of short stories, chapters told to and written down by Ralph Leighton. Feynman tells of his childhood and youth and goes into his adult life, both personally and professionally.', 'https://covers.openlibrary.org/b/id/8826086-M.jpg'),
    ('9781439170915', 'The Emperor of All Maladies', 'Siddhartha Mukherjee', 'Scribner', 2010, 1, 'Popular science', 'The Emperor of All Maladies: A Biography of Cancer is a book written by Siddhartha Mukherjee, an Indian-born American physician and oncologist. Published on 16 November 2010 by Scribner, it won the 2011 Pulitzer Prize for General Non-Fiction.', 'https://covers.openlibrary.org/b/id/12002372-M.jpg'),
    ('9781501144332', 'Why We Sleep', 'Matthew Walker', 'Scribner', 2017, 3, 'Popular science', 'With two appearances on CBS This Morning and Fresh Air''s most popular interview of 2017, Matthew Walker has made abundantly clear that sleep is one of the most important but least understood aspects of our life. Until very recently, science had no answer to the question of why we sleep, or what good it served, or why we suffer such devastating health consequences when it is absent. Compared to the other basic drives in life—eating, drinking, and reproducing—the purpose of sleep remains more elusive. Within the brain, sleep enriches a diversity of functions, including our ability to learn, memorize, and make logical decisions. It recalibrates our emotions, restocks our immune system, fine-tunes our metabolism, and regulates our appetite. Dreaming creates a virtual reality space in which the brain melds past and present knowledge, inspiring creativity.', 'https://covers.openlibrary.org/b/id/14409715-M.jpg'),
    ('9780743219174', 'The Double Helix', 'James D. Watson', 'Scribner', 1968, 2, 'Popular science', 'By identifying the structure of DNA, the molecule of life, Francis Crick and James Watson revolutionized biochemistry and won themselves a Nobel Prize. At the time, Watson was only 24, a young scientist hungry to make his mark. His uncompromisingly honest account of the heady days of their thrilling sprint against other world-class researchers to solve one of science''s greatest mysteries gives a dazzlingly clear picture of a world of brilliant scientists with great gifts, very human ambitions, and bitter rivalries. With humility unspoiled by false modesty, Watson relates his and Crick''s desperate efforts to beat Linus Pauling to the Holy Grail of life sciences, the identification of the basic building block of life. Never has a scientist been so truthful in capturing in words the flavor of his work. - Back cover.', 'https://covers.openlibrary.org/b/id/13872632-M.jpg'),
    ('9781531888121', 'Pale Blue Dot', 'Carl Sagan', 'Brilliance Audio', 1994, 4, 'Popular science', '“Fascinating . . . memorable . . . revealing . . . perhaps the best of Carl Sagan’s books.”—The Washington Post Book World (front page review) In Cosmos, the late astronomer Carl Sagan cast his gaze over the magnificent mystery of the Universe and made it accessible to millions of people around the world. Now in this stunning sequel, Carl Sagan completes his revolutionary journey through space and time. Future generations will look back on our epoch as the time when the human race finally broke into a radically new frontier—space. In Pale Blue Dot, Sagan traces the spellbinding history of our launch into the cosmos and assesses the future that looms before us as we move out into our own solar system and on to distant galaxies beyond.', 'https://covers.openlibrary.org/b/id/12500389-M.jpg'),
    ('9781500808891', 'Beyond Good and Evil', 'Friedrich Nietzsche', 'CreateSpace Independent Publishing Platform', 1886, 2, 'Philosophy', 'Nietzsche attacks the dogmatism of earlier philosophers and of conventional morality, and sketches the free spirits of a philosophy of the future.', NULL),
    ('9781499527681', 'Thus Spoke Zarathustra', 'Friedrich Nietzsche', 'CreateSpace Independent Publishing Platform', 1883, 2, 'Philosophy', 'The prophet Zarathustra comes down from the mountains to preach the death of God, the overman and the eternal recurrence, in poetic, biblical prose.', NULL),
    ('9781554811526', 'Meditations on First Philosophy', 'René Descartes', 'Broadview Press', 1641, 2, 'Philosophy', 'Meditations on First Philosophy (1641)—full titles Meditations on First Philosophy, in which the existence of God and the immortality of the soul are demonstrated—is a philosophical treatise by French philosopher and mathematician René Descartes. First published in Latin, the book is made up of six meditations written as if Descartes had meditated for six days; each meditation refers to the last one as “yesterday.” The author rejects all belief in things that are not absolutely certain and then attempts to establish what can be absolutely certain. Meditations on First Philosophy (1641)—full titles Meditations on First Philosophy, in which the existence of God and the immortality of the soul are demonstrated—is a philosophical treatise by French philosopher and mathematician René Descartes.', 'https://covers.openlibrary.org/b/id/12752049-M.jpg'),
    ('9781985364479', 'Critique of Pure Reason', 'Immanuel Kant', 'Publishers of the Valley', 1781, 0, 'Philosophy', 'Kant examines what reason can know independently of experience, arguing that space, time and causality are forms the mind imposes on the world.', NULL),
    ('9780847707072', 'Leviathan', 'Thomas Hobbes', 'La Editorial Universidad de Puerto Rico', 1651, 1, 'Philosophy', 'Thomas Hobbes'' Leviathan, from 1651, is one of the first and most influential arguments towards social contract. Written in the midst of the English Civil War, it concerns the structure of government and society and argues for strong central governance and the rule of an absolute sovereign as the way to avoid civil war and chaos.', 'https://covers.openlibrary.org/b/id/5145520-M.jpg'),
    ('9789562915410', 'The Social Contract', 'Jean-Jacques Rousseau', 'bnpublishing.com', 1762, 1, 'Philosophy', 'Rousseau argues that legitimate political authority can only come from an agreement among free citizens, expressed through the general will.', 'https://covers.openlibrary.org/b/id/2292601-M.jpg'),
    ('9780344234934', 'Utilitarianism', 'John Stuart Mill', 'Franklin Classics Trade Press', 1863, 1, 'Philosophy', '"Because Utilitarianism is a work of enduring value, it is easy to forget that Mill meant for it to be a topical and relevant contribution to the moral debates of his time. In this edition of Mill''s essay, Colin Heydt situates the work in its historical context by supplementing the text of the essay with appendices containing excerpts of related works by Mill''s predecessors, Mill himself, and prominent critics of his views. The historical richness of this edition of Utilitarianism would surely have pleased Mill, and will surely benefit today''s readers." Ben Eggleston, University of Kansas -- "Colin Heydt has made judicious choices about which additional readings to place alongside Utilitarianism itself.', 'https://covers.openlibrary.org/b/id/11356244-M.jpg'),
    ('9781554810444', 'On Liberty', 'John Stuart Mill', 'Broadview Press', 1859, 0, 'Philosophy', 'Book digitized by Google from the library of the New York Public Library and uploaded to the Internet Archive by user tpb.', 'https://covers.openlibrary.org/b/id/12956749-M.jpg'),
    ('9780394437606', 'The Myth of Sisyphus', 'Albert Camus', 'Knopf', 1942, 2, 'Philosophy', 'One of the most influential works of this century, this is a crucial exposition of existentialist thought. Influenced by works such as Don Juan and the novels of Kafka, these essays begin with a meditation on suicide: the question of living or not living in an absurd universe devoid of order or meaning. With lyric eloquence, Camus posits a way out of despair, reaffirming the value of personal existence, and the possibility of life lived with dignity and authenticity.--From publisher description.', 'https://covers.openlibrary.org/b/id/13779167-M.jpg'),
    ('9789354997174', 'Being and Time', 'Martin Heidegger', 'General Press', 1927, 0, 'Philosophy', 'Heidegger''s lecture course at the University of Marburg in the summer of 1925, an early version of ‘Being and Time’ (1927), offers a unique glimpse into the motivations that prompted the writing of this great philosopher''s masterwork and the presuppositions that gave shape to it.\\ The book embarks upon a provisional description of what Heidegger calls ‘Dasein’, the field in which both being and time become manifest. Heidegger analyzes Dasein in its everydayness in a deepening sequence of terms: being-in-the-world, worldhood, and care as the being of Dasein.\\ The course ends by sketching the themes of death and conscience and their relevance to an ontology that makes the phenomenon of time central.', 'https://covers.openlibrary.org/b/id/15221434-M.jpg'),
    ('9780553212785', 'The Prince', 'Niccolò Machiavelli', 'Bantam Dell', 1532, 2, 'Philosophy', 'The Prince (Italian: Il Principe [il ˈprintʃipe]; Latin: De Principatibus) is a 16th-century political treatise written by Italian diplomat and political theorist Niccolò Machiavelli as an instruction guide for new princes and royals. The general theme of The Prince is of accepting that the aims of princes – such as glory and survival – can justify the use of immoral means to achieve those ends. From Machiavelli''s correspondence, a version appears to have been distributed in 1513, using a Latin title, De Principatibus (Of Principalities). However, the printed version was not published until 1532, five years after Machiavelli''s death. This was carried out with the permission of the Medici pope Clement VII, but "long before then, in fact since the first appearance of The Prince in manuscript, controversy had swirled about his writings".', 'https://covers.openlibrary.org/b/id/14850533-M.jpg'),
    ('9780752818672', 'Sophie''s World', 'Jostein Gaarder', 'Orion Pub. Group', 1991, 1, 'Philosophy', 'A Norwegian schoolgirl receives mysterious letters that lead her through the history of Western philosophy, from Socrates to Sartre, inside a puzzling novel.', 'https://covers.openlibrary.org/b/id/10563354-M.jpg'),
    ('9781567314793', 'Man''s Search for Meaning', 'Viktor E. Frankl', 'MJF Books', 1946, 0, 'Philosophy', 'A psychiatrist''s account of surviving the Nazi concentration camps, and the therapy he built on it: the human drive to find meaning even in suffering.', 'https://covers.openlibrary.org/b/id/809683-M.jpg'),
    ('9780061908026', 'Zen and the Art of Motorcycle Maintenance', 'Robert M. Pirsig', 'HarperCollins Publishers', 1974, 1, 'Philosophy', '"The real cycle you''re working on is a cycle called ''yourself.''"One of the most important and influential books of the past half-century, Robert M. Pirsig''s Zen and the Art of Motorcycle Maintenance is a powerful, moving, and penetrating examination of how we live and a meditation on how to live better. The narrative of a father on a summer motorcycle trip across America''s Northwest with his young son, it becomes a profound personal and philosophical odyssey into life''s fundamental questions. A true modern classic, it remains at once touching and transcendent, resonant with the myriad confusions of existence and the small, essential triumphs that propel us forward.', 'https://covers.openlibrary.org/b/id/15182815-M.jpg'),
    ('9781442346277', 'Steve Jobs', 'Walter Isaacson', 'Simon & Schuster Audio', 2011, 1, 'Biography', 'Based on more than forty interviews with Jobs conducted over two years -- as well as interviews with more than a hundred family members, friends, adversaries, competitors, and colleagues -- Walter Isaacson has written a riveting story of the roller-coaster life and searingly intense personality of a creative entrepreneur whose passion for perfection and ferocious drive revolutionized six industries: personal computers, animated movies, music, phones, tablet computing, and digital publishing. At a time when America is seeking ways to sustain its innovative edge, and when societies around the world are trying to build digital-age economies, Jobs stands as the ultimate icon of inventiveness and applied imagination. He knew that the best way to create value in the twenty-first century was to connect creativity with technology.', 'https://covers.openlibrary.org/b/id/13304736-M.jpg'),
    ('9780349107530', 'Long Walk to Freedom', 'Nelson Mandela', 'TIME WARNER PAPERBACKS', 1994, 2, 'Biography', 'The riveting memoirs of the outstanding moral and political leader of our time, Long Walk to Freedom brilliantly recreates the drama of the experiences that helped shape Nelson Mandela''s destiny. Emotive, compelling and uplifting, Long Walk to Freedom is the exhilarating story of an epic life; a story of hardship, resilience and ultimate triumph told with the clarity and eloquence of a born leader.', 'https://covers.openlibrary.org/b/id/12702407-M.jpg'),
    ('9780593303740', 'Becoming', 'Michelle Obama', 'Delacorte Books for Young Readers', 2018, 0, 'Biography', 'IN A LIFE filled with meaning and accomplishment, Michelle Obama has emerged as one of the most iconic and compelling women of our era. As First Lady of the United States of America—the first African American to serve in that role—she helped create the most welcoming and inclusive White House in history, while also establishing herself as a powerful advocate for women and girls in the U.S. and around the world, dramatically changing the ways that families pursue healthier and more active lives, and standing with her husband as he led America through some of its most harrowing moments. Along the way, she showed us a few dance moves, crushed Carpool Karaoke, and raised two down-to-earth daughters under an unforgiving media glare.', 'https://covers.openlibrary.org/b/id/10618645-M.jpg'),
    ('9781987146127', 'Educated', 'Tara Westover', 'Random House Audio', 2018, 3, 'Biography', 'Educated is a 2018 memoir by the American author Tara Westover. Westover recounts overcoming her survivalist Mormon family in order to go to college, and emphasizes the importance of education in enlarging her world. She details her journey from her isolated life in the mountains of Idaho to completing a PhD program in history at Cambridge University. She started college at the age of 17 having had no formal education. She explores her struggle to reconcile her desire to learn with the world she inhabited with her father.', 'https://covers.openlibrary.org/b/id/15216613-M.jpg'),
    ('9780307292018', 'I Know Why the Caged Bird Sings', 'Maya Angelou', 'Random House', 1969, 4, 'Biography', 'She was born Marguerite, but her brother Bailey nicknamed her Maya ("mine"). As little children they were sent to live with their grandmother in Stamps, Arkansas. Their early world revolved around this remarkable woman and the Store she ran for the black community. White people were more than strangers - they were from another planet. And yet, even unseen they ruled. The Store was a microcosm of life: its orderly pattern was a comfort, even among the meanest frustrations. But then came the intruders - first in the form of taunting poorwhite children who were bested only by the grandmother''s dignity. But as the awful, unfathomable mystery of prejudice intruded, so did the unexpected joy of a surprise visit by Daddy, the sinful joy of going to Church, the disappointments of a Depression Christmas. A visit to St. Louis and the Most Beautiful Mother in the World ended in tragedy - rape.', 'https://covers.openlibrary.org/b/id/15204141-M.jpg'),
    ('9781770105065', 'Born a Crime', 'Trevor Noah', 'Macmillan', 2016, 2, 'Biography', 'Born a Crime is the story of a mischievous young boy who grows into a restless young man as he struggles to find himself in a world where he was never supposed to exist. It is also the story of that young man’s relationship with his fearless, rebellious, and fervently religious mother—his teammate, a woman determined to save her son from the cycle of poverty, violence, and abuse that would ultimately threaten her own life. The stories collected here are by turns hilarious, dramatic, and deeply affecting. Whether subsisting on caterpillars for dinner during hard times, being thrown from a moving car during an attempted kidnapping, or just trying to survive the life-and-death pitfalls of dating in high school, Trevor illuminates his curious world with an incisive wit and unflinching honesty.', 'https://covers.openlibrary.org/b/id/12063864-M.jpg'),
    ('9780679450252', 'Into the Wild', 'Jon Krakauer', 'Brand: Random House Audio', 1996, 4, 'Biography', 'In April 1992 a young man from a well-to-do family hitchhiked to Alaska and walked alone into the wilderness north of Mt. McKinley. His name was Christopher Johnson McCandless. He had given $25,000 in savings to charity, abandoned his car and most of his possessions, burned all the cash in his wallet, and invented a new life for himself. Four months later, his decomposed body was found by a moose hunter. How McCandless came to die is the unforgettable story of Into the Wild. Immediately after graduating from college in 1991, McCandless had roamed through the West and Southwest on a vision quest like those made by his heroes Jack London and John Muir. In the Mojave Desert he abandoned his car, stripped it of its license plates, and burned all of his cash.', 'https://covers.openlibrary.org/b/id/13537992-M.jpg'),
    ('9781524708658', 'Alexander Hamilton', 'Ron Chernow', 'Penguin Random House Audio', 2004, 3, 'Biography', 'From National Book Award winner Ron Chernow, a landmark biography of Alexander Hamilton, the Founding Father who galvanized, inspired, scandalized, and shaped the newborn nation.In the first full-length biography of Alexander Hamilton in decades, National Book Award winner Ron Chernow tells the riveting story of a man who overcame all odds to shape, inspire, and scandalize the newborn America. According to historian Joseph Ellis, Alexander Hamilton is "a robust full-length portrait, in my view the best ever written, of the most brilliant, charismatic and dangerous founder of them all."Few figures in American history have been more hotly debated or more grossly misunderstood than Alexander Hamilton.', 'https://covers.openlibrary.org/b/id/14630111-M.jpg'),
    ('9780812988406', 'When Breath Becomes Air', 'Paul Kalanithi', 'Random House', 2016, 1, 'Biography', 'When Breath Becomes Air is a non-fiction autobiographical book written by American neurosurgeon Paul Kalanithi. It is a memoir about his life and illness, battling stage IV metastatic lung cancer. It was posthumously published by Random House on January 12, 2016.', 'https://covers.openlibrary.org/b/id/12390254-M.jpg'),
    ('9780756963804', 'Night', 'Elie Wiesel', 'Perfection Learning', 1956, 0, 'Biography', 'An autobiographical narrative in which the author describes his experiences in Nazi concentration camps, watching family and friends die, and how they led him to believe that God is dead.', 'https://covers.openlibrary.org/b/id/7732021-M.jpg'),
    ('9781471170119', 'Shoe Dog', 'Phil Knight', 'Simon & Schuster, Limited', 2016, 2, 'Biography', '"In this candid and riveting memoir, for the first time ever, Nike founder and CEO Phil Knight shares the inside story of the company''s early days as an intrepid start-up and its evolution into one of the world''s most iconic, game-changing, and profitable brands. In 1962, fresh out of business school, Phil Knight borrowed $50 from his father and created a company with a simple mission: import high-quality, low-cost athletic shoes from Japan. Selling the shoes from the trunk of his lime green Plymouth Valiant, Knight grossed $8,000 his first year. Today, Nike''s annual sales top $30 billion. In an age of startups, Nike is the ne plus ultra of all startups, and the swoosh has become a revolutionary, globe-spanning icon, one of the most ubiquitous and recognizable symbols in the world today. But Knight, the man behind the swoosh, has always remained a mystery.', 'https://covers.openlibrary.org/b/id/14850526-M.jpg'),
    ('9781927970164', 'Twelve Years a Slave', 'Solomon Northup', 'Engage Books', 1853, 0, 'Biography', 'Twelve Years a Slave is a harrowing memoir about one of the darkest periods in American history. It recounts how Solomon Northup, born a free man in New York, was lured to Washington, D.C., in 1841 with the promise of fast money, then drugged and beaten and sold into slavery. He spent the next twelve years of his life in captivity on a Louisiana cotton plantation.', 'https://covers.openlibrary.org/b/id/10683761-M.jpg'),
    ('9780679424734', 'The Wealth of Nations', 'Adam Smith', 'Modern Library Inc', 1776, 4, 'Economics', 'Adam Smith''s The Wealth of Nations was recognized as a landmark of human thought upon its publication in 1776. As the first scientific argument for the principles of political economy, it is the point of departure for all subsequent economic thought. Smith''s theories of capital accumulation, growth, and secular change, among others, continue to be influential in modern economics. This reprint of Edwin Cannan''s definitive 1904 edition of The Wealth of Nations includes Cannan''s famous introduction, notes, and a full index, as well as a new preface written especially for this edition by the distinguished economist George J. Stigler. Mr. Stigler''s preface will be of value for anyone wishing to see the contemporary relevance of Adam Smith''s thought.', 'https://covers.openlibrary.org/b/id/15264463-M.jpg'),
    ('9781912302307', 'Capital in the Twenty-First Century', 'Thomas Piketty', 'Taylor & Francis Group', 2013, 0, 'Economics', 'Using two centuries of tax and income data, Piketty shows that the return on capital tends to exceed economic growth, so wealth concentrates unless policy intervenes.', 'https://covers.openlibrary.org/b/id/13314970-M.jpg'),
    ('9780061242700', 'Freakonomics', 'Steven D. Levitt, Stephen J. Dubner', 'HarperTorch', 2005, 2, 'Economics', 'A Rogue Economist Explores the Hidden Side of Everything Which is more dangerous, a gun or a swimming pool? What do schoolteachers and sumo wrestlers have in common? Why do drug dealers still live with their moms? How much do parents really matter? How did the legalization of abortion affect the rate of violent crime? These may not sound like typical questions for an economist to ask. But Steven D. Levitt is not a typical economist. He is a much-heralded scholar who studies the riddles of everyday life—from cheating and crime to sports and child-rearing—and whose conclusions turn the conventional wisdom on its head. Freakonomics is a ground-breaking collaboration between Levitt and Stephen J. Dubner, an award-winning author and journalist. They usually begin with a mountain of data and a simple, unasked question.', 'https://covers.openlibrary.org/b/id/14849328-M.jpg'),
    ('9780333009420', 'The General Theory of Employment, Interest and Money', 'John Maynard Keynes', 'Palgrave Macmillan', 1936, 1, 'Economics', 'Keynes argues that economies can stay stuck with high unemployment because demand is too low, and that governments should act to raise it.', 'https://covers.openlibrary.org/b/id/2389005-M.jpg'),
    ('9780226320786', 'The Road to Serfdom', 'Friedrich Hayek', 'University of Chicago Press', 1944, 0, 'Economics', 'A classic work in political philosophy, intellectual and cultural history, and economics, The Road to Serfdom has inspired and infuriated politicians, scholars, and general readers for half a century. Originally published in England in the spring of 1944 - when the Labour party ruled in Britain, Eleanor Roosevelt supported the efforts of Stalin, and Albert Einstein subscribed to the socialist program - The Road to Serfdom was seen as heretical for its passionate warning against the dangers of state control over the means of production. For F.A. Hayek, the collectivist idea of empowering government with increasing economic control would inevitably lead not to a utopia but to the horrors of Nazi Germany and Fascist Italy.', 'https://covers.openlibrary.org/b/id/7323234-M.jpg'),
    ('9780786100491', 'Capitalism and Freedom', 'Milton Friedman', 'Blackstone Audiobooks', 1962, 2, 'Economics', 'Selected by the Times Literary Supplement as one of the "hundred most influential books since the war"How can we benefit from the promise of government while avoiding the threat it poses to individual freedom? In this classic book, Milton Friedman provides the definitive statement of his immensely influential economic philosophy—one in which competitive capitalism serves as both a device for achieving economic freedom and a necessary condition for political freedom. The result is an accessible text that has sold well over half a million copies in English, has been translated into eighteen languages, and shows every sign of becoming more and more influential as time goes on.', 'https://covers.openlibrary.org/b/id/14263987-M.jpg'),
    ('9780342972289', 'Capital', 'Karl Marx', 'Franklin Classics', 1867, 3, 'Economics', 'Marx analyses capitalism as a system built on extracting surplus value from labour, and traces its tendencies toward crisis and concentration.', 'https://covers.openlibrary.org/b/id/11577265-M.jpg'),
    ('9780593243657', 'The Black Swan', 'Nassim Nicholas Taleb', 'Random House', 2007, 3, 'Economics', 'From the critically acclaimed author of Fooled by Randomness, a book about the impact of improbable events on every aspect of life.', 'https://covers.openlibrary.org/b/id/12954227-M.jpg'),
    ('9780300262285', 'Nudge', 'Richard H. Thaler, Cass R. Sunstein', 'Yale University Press', 2008, 1, 'Economics', 'Thaler and Sunstein develop libertarian paternalism as a middle path between command-and-control and strict-neutrality choice architectures. Libertarian paternalism protects humans against their damaging psychological traits (inertia, bounded rationality, undue influence) by exploiting those habits to nudge people into making better choices.', 'https://covers.openlibrary.org/b/id/11515486-M.jpg'),
    ('9780141043531', 'The Big Short', 'Michael Lewis', 'W. W. Norton & Co', 2010, 2, 'Economics', 'The #1 New York Times bestseller: a brilliant account—character-rich and darkly humorous—of how the U.S. economy was driven over the cliff. When the crash of the U. S. stock market became public knowledge in the fall of 2008, it was already old news. The real crash, the silent crash, had taken place over the previous year, in bizarre feeder markets where the sun doesn’t shine, and the SEC doesn’t dare, or bother, to tread: the bond and real estate derivative markets where geeks invent impenetrable securities to profit from the misery of lower- and middle-class Americans who can’t pay their debts. The smart people who understood what was or might be happening were paralyzed by hope and fear; in any case, they weren’t talking.', 'https://covers.openlibrary.org/b/id/8769168-M.jpg'),
    ('9780718193669', 'Poor Economics', 'Abhijit Banerjee, Esther Duflo', 'Penguin Books, Limited', 2011, 2, 'Economics', '"Billions of government dollars, and thousands of charitable organizations and NGOs, are dedicated to helping the world''s poor. But much of the work they do is based on assumptions that are untested generalizations at best, flat out harmful misperceptions at worst. Banerjee and Duflo have pioneered the use of randomized control trials in development economics. Work based on these principles, supervised by the Poverty Action Lab at MIT, is being carried out in dozens of countries. Their work transforms certain presumptions: that microfinance is a cure-all, that schooling equals learning, that poverty at the level of 99 cents a day is just a more extreme version of the experience any of us have when our income falls uncomfortably low.', 'https://covers.openlibrary.org/b/id/12842198-M.jpg'),
    ('9781846684296', 'Why Nations Fail', 'Daron Acemoglu, James A. Robinson', 'Profile Books', 2012, 2, 'Economics', 'Why are some nations rich and others poor, divided by wealth and poverty, health and sickness, food and famine? Is it culture, the weather, or geography that determines prosperity or poverty? As Why Nations Fail shows, none of these factors is either definitive or destiny. Drawing on fifteen years of original research, Daron Acemoglu and James Robinson conclusively show that it is our man-made political and economic institutions that underlie economic success (or the lack of it). Korea, to take just one example, is a remarkably homogeneous nation, yet the people of North Korea are among the poorest on earth while their brothers and sisters in South Korea are among the richest. The differences between the Koreas is due to the politics that created those two different institutional trajectories.', 'https://covers.openlibrary.org/b/id/12026426-M.jpg'),
    ('9780063497474', 'The Intelligent Investor', 'Benjamin Graham', 'Harper Business', 1949, 4, 'Economics', 'This classic text is annotated to update Graham''s timeless wisdom for today''s market conditions... The greatest investment advisor of the twentieth century, Benjamin Graham, taught and inspired people worldwide. Graham''s philosophy of "value investing" -- which shields investors from substantial error and teaches them to develop long-term strategies -- has made The Intelligent Investor the stock market bible ever since its original publication in 1949. Over the years, market developments have proven the wisdom of Graham''s strategies.', 'https://covers.openlibrary.org/b/id/15236195-M.jpg'),
    ('9781464166174', 'Thinking, Fast and Slow', 'Daniel Kahneman', 'Worth Publishers, Incorporated', 2011, 1, 'Economics', 'In his mega bestseller, Thinking, Fast and Slow, Daniel Kahneman, world-famous psychologist and winner of the Nobel Prize in Economics, takes us on a groundbreaking tour of the mind and explains the two systems that drive the way we think. System 1 is fast, intuitive, and emotional; System 2 is slower, more deliberative, and more logical. The impact of overconfidence on corporate strategies, the difficulties of predicting what will make us happy in the future, the profound effect of cognitive biases on everything from playing the stock market to planning our next vacation―each of these can be understood only by knowing how the two systems shape our judgments and decisions. Engaging the reader in a lively conversation about how we think, Kahneman reveals where we can and cannot trust our intuitions and how we can tap into the benefits of slow thinking.', 'https://covers.openlibrary.org/b/id/13290715-M.jpg'),
    ('9781501238703', 'Misbehaving', 'Richard H. Thaler', 'Audible Studios on Brilliance Audio', 2015, 1, 'Economics', 'Nobel laureate Richard H. Thaler has spent his career studying the radical notion that the central agents in the economy are humans―predictable, error-prone individuals. Misbehaving is his arresting, frequently hilarious account of the struggle to bring an academic discipline back down to earth―and change the way we think about economics, ourselves, and our world. Traditional economics assumes rational actors. Early in his research, Thaler realized these Spock-like automatons were nothing like real people. Whether buying a clock radio, selling basketball tickets, or applying for a mortgage, we all succumb to biases and make decisions that deviate from the standards of rationality assumed by economists. In other words, we misbehave. More importantly, our misbehavior has serious consequences.', 'https://covers.openlibrary.org/b/id/11623303-M.jpg'),
    ('9780131175327', 'The C Programming Language', 'Brian W. Kernighan, Dennis M. Ritchie', 'Prentice Hall', 1978, 2, 'Programming', 'Very well known, classic introduction to the C Programming Language. Both a text for learning, a reference, and, to some, the definition of proper C language features and use.', 'https://covers.openlibrary.org/b/id/6921000-M.jpg'),
    ('9780262010771', 'Structure and Interpretation of Computer Programs', 'Harold Abelson, Gerald Jay Sussman', 'MIT Press', 1985, 1, 'Programming', '> Wizard Book n. Hal Abelson''s, Jerry Sussman''s and Julie Sussman''s Structure and Interpretation of Computer Programs (MIT Press, 1984; ISBN 0-262-01077-1), an excellent computer science text used in introductory courses at MIT. So called because of the wizard on the jacket. One of the bibles of the LISP/Scheme world. Also, less commonly, known as the Purple Book. from The New Hacker''s Dictionary, 2nd edition (MIT Press, 1993)', 'https://covers.openlibrary.org/b/id/6808441-M.jpg'),
    ('9780735691254', 'Code Complete', 'Steve McConnell', 'Microsoft Press', 1993, 2, 'Programming', 'Take a strategic approach to software construction—and produce superior products—with this fully updated edition of Steve McConnell''s critically praised and award-winning guide to software development best practices. Widely considered one of the best practical guides to programming, Steve McConnell''s original CODE COMPLETE has been helping developers write better software for more than a decade. Now this classic book has been fully updated and revised with leading-edge practices—and hundreds of new code samples—illustrating the art and science of software construction. Capturing the body of knowledge available from research, academia, and everyday commercial practice, McConnell synthesizes the most effective techniques and must-know principles into clear, pragmatic guidance.', 'https://covers.openlibrary.org/b/id/6416062-M.jpg'),
    ('9780132119160', 'The Mythical Man-Month', 'Frederick P. Brooks', 'Addison Wesley', 1975, 1, 'Programming', 'Classic text on the human side of software engineering, containing essays on the management of software teams, projections about how computer languages and tools will evolve, and philosophical speculation. Unlike most other books about computing, Brooks'' work has been remarkably enduring, remaining in print for at least four decades. The book is most famous for its statement of Brooks'' Law: "adding manpower to a late software project makes it later".', 'https://covers.openlibrary.org/b/id/15178083-M.jpg'),
    ('9780132931755', 'Working Effectively with Legacy Code', 'Michael C. Feathers', 'Pearson Education Canada', 2004, 3, 'Programming', 'Techniques for safely changing large codebases that have no tests: finding seams, breaking dependencies and getting code under test before refactoring it.', 'https://covers.openlibrary.org/b/id/14430328-M.jpg'),
    ('9780321125217', 'Domain-Driven Design', 'Eric Evans', 'Addison-Wesley', 2003, 2, 'Programming', 'How to tackle complex software by modelling the business domain together with experts: ubiquitous language, entities, aggregates and bounded contexts.', 'https://covers.openlibrary.org/b/id/14596704-M.jpg'),
    ('9781492078005', 'Head First Design Patterns', 'Eric Freeman, Elisabeth Robson', 'O''Reilly Media, Incorporated', 2004, 2, 'Programming', 'A visual, conversational introduction to object-oriented design patterns such as Strategy, Observer, Decorator and Factory, with Java examples.', 'https://covers.openlibrary.org/b/id/13345163-M.jpg'),
    ('9780201791204', 'Effective Java', 'Joshua Bloch', 'Addison-Wesley Pub (Sd)', 2001, 1, 'Programming', 'Best-practice advice for the Java language and libraries: object creation, generics, enums, lambdas and streams, concurrency and API design.', 'https://covers.openlibrary.org/b/id/2334826-M.jpg'),
    ('9781515367185', 'JavaScript: The Good Parts', 'Douglas Crockford', 'CreateSpace Independent Publishing Platform', 2008, 1, 'Programming', 'Crockford separates the elegant core of JavaScript, its functions, objects and closures, from the parts of the language that are better avoided.', NULL),
    ('9781593279509', 'Eloquent JavaScript', 'Marijn Haverbeke', 'No Starch Press', 2011, 2, 'Programming', 'JavaScript lies at the heart of almost every modern web application, from social apps like Twitter to browser-based game frameworks like Phaser and Babylon. Though simple for beginners to pick up and play with, JavaScript is a flexible, complex language that you can use to build full-scale applications. This much anticipated and thoroughly revised third edition of Eloquent JavaScript dives deep into the JavaScript language to show you how to write beautiful, effective code. It has been updated to reflect the current state of Java¬Script and web browsers and includes brand-new material on features like class notation, arrow functions, iterators, async functions, template strings, and block scope. A host of new exercises have also been added to test your skills and keep you on track.', 'https://covers.openlibrary.org/b/id/8508178-M.jpg'),
    ('9781593276034', 'Python Crash Course', 'Eric Matthes', 'No Starch Press', 2015, 2, 'Programming', 'A hands-on introduction to programming in Python, from the basics to three projects: a game, data visualisations and a web application.', 'https://covers.openlibrary.org/b/id/8245395-M.jpg'),
    ('9781492056355', 'Fluent Python', 'Luciano Ramalho', 'O’Reilly Media', 2015, 4, 'Programming', 'A deep tour of idiomatic Python: the data model, sequences, functions as objects, iterators and generators, concurrency and metaprogramming.', 'https://covers.openlibrary.org/b/id/10290195-M.jpg'),
    ('9780134494326', 'Clean Architecture', 'Robert C. Martin', 'Pearson Education, Limited', 2017, 0, 'Programming', 'Principles for structuring software so that business rules stay independent of frameworks, databases and user interfaces.', 'https://covers.openlibrary.org/b/id/15093860-M.jpg'),
    ('9780201896855', 'The Art of Computer Programming', 'Donald E. Knuth', 'Addison-Wesley Pub. Co.', 1968, 2, 'Programming', 'Knuth''s multi-volume treatise on algorithms and their mathematical analysis: fundamental algorithms, seminumerical algorithms, sorting and searching.', 'https://covers.openlibrary.org/b/id/8057262-M.jpg'),
    ('9780984782864', 'Cracking the Coding Interview', 'Gayle Laakmann McDowell', 'CareerCup', 2008, 0, 'Programming', 'I am not a recruiter. I am a software engineer. And as such, I know what it''s like to be asked to whip up brilliant algorithms on the spot and then write flawless code on a whiteboard. I''ve been through this as a candidate and as an interviewer. Cracking the Coding Interview, 6th Edition is here to help you through this process, teaching you what you need to know and enabling you to perform at your very best. I''ve coached and interviewed hundreds of software engineers. The result is this book. Learn how to uncover the hints and hidden details in a question, discover how to break down a problem into manageable chunks, develop techniques to unstick yourself when stuck, learn (or re-learn) core computer science concepts, and practice on 189 interview questions and solutions. These interview questions are real; they are not pulled out of computer science textbooks.', 'https://covers.openlibrary.org/b/id/12377283-M.jpg'),
    ('9781072943785', 'Artificial Intelligence: A Modern Approach', 'Stuart Russell, Peter Norvig', 'Independently Published', 1995, 3, 'Artificial intelligence', 'The standard textbook on artificial intelligence: intelligent agents, search, logic, planning, probabilistic reasoning, machine learning, language and robotics.', NULL),
    ('9781501227745', 'Superintelligence', 'Nick Bostrom', 'Audible Studios on Brilliance', 2014, 2, 'Artificial intelligence', 'The human brain has some capabilities that the brains of other animals lack. It is to these distinctive capabilities that our species owes its dominant position. Other animals have stronger muscles or sharper claws, but we have cleverer brains. If machine brains one day come to surpass human brains in general intelligence, then this new superintelligence could become very powerful. As the fate of the gorillas now depends more on us humans than on the gorillas themselves, so the fate of our species then would come to depend on the actions of the machine superintelligence. But we have one advantage: we get to make the first move.', 'https://covers.openlibrary.org/b/id/11416260-M.jpg'),
    ('9780525558637', 'Human Compatible', 'Stuart Russell', 'Penguin Books', 2019, 1, 'Artificial intelligence', '"In the popular imagination, superhuman artificial intelligence is an approaching tidal wave that threatens not just jobs and human relationships, but civilization itself. Conflict between humans and machines is seen as inevitable and its outcome all too predictable. In this groundbreaking book, distinguished AI researcher Stuart Russell argues that this scenario can be avoided, but only if we rethink AI from the ground up. Russell begins by exploring the idea of intelligence in humans and in machines. He describes the near-term benefits we can expect, from intelligent personal assistants to vastly accelerated scientific research, and outlines the AI breakthroughs that still have to happen before we reach superhuman AI. He also spells out the ways humans are already finding to misuse AI, from lethal autonomous weapons to viral sabotage.', 'https://covers.openlibrary.org/b/id/11264186-M.jpg'),
    ('9780241237199', 'Life 3.0', 'Max Tegmark', 'Allen Lane', 2017, 2, 'Artificial intelligence', '"How will artificial intelligence affect crime, war, justice, jobs, society and our very sense of being human? The rise of AI has the potential to transform our future more than any other technology--and there''s nobody better qualified or situated to explore that future than Max Tegmark, an MIT professor who''s helped mainstream research on how to keep AI beneficial.', 'https://covers.openlibrary.org/b/id/8228445-M.jpg'),
    ('9780241004548', 'The Master Algorithm', 'Pedro Domingos', 'Allen Lane', 2015, 4, 'Artificial intelligence', 'In the world''s top research labs and universities, the race is on to invent the ultimate learning algorithm: one capable of discovering any knowledge from data, and doing anything we want, before we even ask. In The Master Algorithm, Pedro Domingos lifts the veil to give us a peek inside the learning machines that power Google, Amazon, and your smartphone. He assembles a blueprint for the future universal learner--the Master Algorithm--and discusses what it will mean for business, science, and society. If data-ism is today''s philosophy, this book is its bible.', 'https://covers.openlibrary.org/b/id/11969556-M.jpg'),
    ('9780387310732', 'Pattern Recognition and Machine Learning', 'Christopher M. Bishop', 'Springer', 2006, 4, 'Artificial intelligence', 'A machine learning textbook written from a Bayesian perspective: probability distributions, linear models, kernel methods, graphical models and approximate inference.', 'https://covers.openlibrary.org/b/id/245089-M.jpg'),
    ('9780387848570', 'The Elements of Statistical Learning', 'Trevor Hastie, Robert Tibshirani, Jerome Friedman', 'Springer-Verlag New York', 2001, 0, 'Artificial intelligence', 'Describes important statistical ideas in machine learning, data mining, and bioinformatics. Covers a broad range, from supervised learning (prediction), to unsupervised learning, including classification trees, neural networks, and support vector machines.', 'https://covers.openlibrary.org/b/id/8643961-M.jpg'),
    ('9780855277574', 'Gödel, Escher, Bach', 'Douglas R. Hofstadter', 'Harvester Press', 1979, 2, 'Artificial intelligence', 'Winner of the Pulitzer Prize A metaphorical fugue on minds and machines in the spirit of Lewis Carroll Douglas Hofstadter''s book is concerned directly with the nature of "maps" or links between formal systems. However, according to Hofstadter, the formal system that underlies all mental activity transcends the system that supports it. If life can grow out of the formal chemical substrate of the cell, if consciousness can emerge out of a formal system of firing neurons, then so too will computers attain human intelligence. Gödel, Escher, Bach is a wonderful exploration of fascinating ideas at the heart of cognitive science: meaning, reduction, recursion, and much more.', 'https://covers.openlibrary.org/b/id/10193953-M.jpg'),
    ('9780230026827', 'I, Robot', 'Isaac Asimov', 'Macmillan', 1950, 3, 'Artificial intelligence', 'I, Robot is a fixup novel of science fiction short stories or essays by American writer Isaac Asimov. The stories originally appeared in the American magazines Super Science Stories and Astounding Science Fiction between 1940 and 1950 and were then compiled into a book for stand-alone publication by Gnome Press in 1950, in an initial edition of 5,000 copies. The stories are woven together by a framing narrative in which the fictional Dr. Susan Calvin tells each story to a reporter (who serves as the narrator) in the 21st century. Although the stories can be read separately, they share a theme of the interaction of humans, robots, and morality, and when combined they tell a larger story of Asimov''s fictional history of robotics.', 'https://covers.openlibrary.org/b/id/7449753-M.jpg'),
    ('9781786494306', 'The Alignment Problem', 'Brian Christian', 'Atlantic Books', 2020, 2, 'Artificial intelligence', '"A jaw-dropping exploration of everything that goes wrong when we build AI systems-and the movement to fix them. Today''s "machine-learning" systems, trained by data, are so effective that we''ve invited them to see and hear for us-and to make decisions on our behalf. But alarm bells are ringing. Systems cull résumés until, years later, we discover that they have inherent gender biases. Algorithms decide bail and parole-and appear to assess black and white defendants differently. We can no longer assume that our mortgage application, or even our medical tests, will be seen by human eyes. And autonomous vehicles on our streets can injure or kill. When systems we attempt to teach will not, in the end, do what we want or what we expect, ethical and potentially existential risks emerge. Researchers call this the alignment problem.', 'https://covers.openlibrary.org/b/id/13873519-M.jpg'),
    ('9780553418835', 'Weapons of Math Destruction', 'Cathy O''Neil', 'Crown', 2016, 3, 'Artificial intelligence', 'A former Wall Street quant sounds an alarm on the mathematical models that pervade modern life — and threaten to rip apart our social fabric We live in the age of the algorithm. Increasingly, the decisions that affect our lives—where we go to school, whether we get a car loan, how much we pay for health insurance—are being made not by humans, but by mathematical models. In theory, this should lead to greater fairness: Everyone is judged according to the same rules, and bias is eliminated. But as Cathy O’Neil reveals in this urgent and necessary book, the opposite is true. The models being used today are opaque, unregulated, and uncontestable, even when they’re wrong.', 'https://covers.openlibrary.org/b/id/14632952-M.jpg'),
    ('9781978632844', 'AI Superpowers', 'Kai-Fu Lee', 'Brilliance Audio', 2018, 0, 'Artificial intelligence', 'The United States has long been the leader in Artificial Intelligence. But Dr. Kai-Fu Lee--one of the world''s most respected experts on AI--reveals that China has caught up to the US at an astonishingly rapid pace. As Sino-American competition in AI heats up, Lee envisions China and the US forming a powerful duopoly in AI. He outlines the upheaval of traditional jobs, how the suddenly unemployed will find new ways of making their lives meaningful, and how the Chinese and American governments will have to cope with the changing economic landscape. "Kai-Fu Lee--one of the world''s most respected experts on AI and China--reveals that China has suddenly caught up to the United States at an astonishingly rapid and unexpected pace.', 'https://covers.openlibrary.org/b/id/13666428-M.jpg'),
    ('9780935382051', 'Machine Learning', 'Tom M. Mitchell', 'Morgan Kaufmann Pub', 1997, 2, 'Artificial intelligence', 'An introductory textbook covering concept learning, decision trees, neural networks, Bayesian learning, instance-based learning and reinforcement learning.', 'https://covers.openlibrary.org/b/id/4802923-M.jpg'),
    ('9780571374892', 'Klara and the Sun', 'Kazuo Ishiguro', 'Faber & Faber, Limited', 2021, 3, 'Artificial intelligence', '"Klara and the Sun, the first novel by Kazuo Ishiguro since he was awarded the Nobel Prize in Literature, tells the story of Klara, an Artificial Friend with outstanding observational qualities, who, from her place in the store, watches carefully the behavior of those who come in to browse, and of those who pass on the street outside. She remains hopeful that a customer will soon choose her. Klara and the Sun is a thrilling book that offers a look at our changing world through the eyes of an unforgettable narrator, and one that explores the fundamental question: what does it mean to love? In its award citation in 2017, the Nobel committee described Ishiguro''s books as "novels of great emotional force" and said he has "uncovered the abyss beneath our illusory sense of connection with the world.""', 'https://covers.openlibrary.org/b/id/12403410-M.jpg'),
    ('9780140282023', 'The Age of Spiritual Machines', 'Ray Kurzweil', 'Penguin Books', 1999, 3, 'Artificial intelligence', 'Imagine a world where the difference between man and machine blurs, where the line between humanity and technology fades, and where the soul and the silicon chip unite. This is not science fiction. This is the twenty-first century according to Ray Kurzweil, the inventor of the most innovative and compelling technology of our era. In his inspired hands, life in the new millennium no longer seems daunting. Instead, it promises to be an age in which the marriage of human sensitivity and artificial intelligence fundamentally alters and improves the way we live.', 'https://covers.openlibrary.org/b/id/7343904-M.jpg'),
    ('9781789955750', 'Python Machine Learning', 'Sebastian Raschka', 'Packt Publishing', 2015, 2, 'Artificial intelligence', 'Machine learning and predictive analytics are transforming the way businesses and other organizations operate. Being able to understand trends and patterns in complex data is critical to success, becoming one of the key strategies for unlocking growth in a challenging contemporary marketplace. Python can help you deliver key insights into your data -- its unique capabilities as a language let you build sophisticated algorithms and statistical models that can reveal new perspectives and answer key questions that are vital for success. Python Machine Learning gives you access to the world of predictive analytics and demonstrates why Python is one of the world''s leading data science languages. If you want to ask better questions of data, or need to improve and extend the capabilities of your machine learning systems, this practical data science book is invaluable.', 'https://covers.openlibrary.org/b/id/10144350-M.jpg');
